import type { Color } from 'claude-code'

import type { Lang, MemberId, Mood, Phrase, Role, Roles, Task, WorkRole } from '../types'

import { EN } from './cast.en'
import { JA } from './cast.ja'
import { KO } from './cast.ko'
import { asIs, inAll, LANGS } from './words'

/** What a character is whatever the language: its mark, its own role, whether it talks, its colors. */
export type Member = {
  id: MemberId
  /** A mark in plain text, for a toast and an agent's description. */
  mark: string
  role: Role
  /** Whether the character says whole sentences in the comic. */
  speaks: boolean
  /** The symbol color: the name badge. */
  color: string
  ink: string
  /** The same hue as a line on a dark terminal; `toneOf` gives its fellow for a light one. */
  line: Color
}

export const PINK = '#f7a8c0'
export const LEAD: MemberId = 'hachiware'
/** The three the comic is about: always on the page, whatever they are doing. */
export const CORE: readonly MemberId[] = ['hachiware', 'chiikawa', 'usagi']

// The pastel hues are drawn for a dark terminal; on a light one each gives
// way to a deeper fellow that reads against white.
const ON_LIGHT: Readonly<Record<string, string>> = {
  '#6fa0ea': '#2f62b8',
  '#f7a8c0': '#c2457a',
  '#f3dc6b': '#8a6d00',
  '#d8c36a': '#7a6a1c',
  '#e0605a': '#b8322c',
  '#f08a24': '#b05a00',
  '#f6c9a0': '#a8703a',
  '#c08a52': '#7a4a1e',
  '#f0dcb4': '#9a7a3c',
  '#e8566a': '#b82f48',
  '#f29bb0': '#c23a66',
  '#c9c9c9': '#6e6e6e',
  '#f48fb1': '#b8477a',
  '#a8d8f0': '#1f7fa8',
  '#a89f91': '#6b6257',
}

/** One of this mod's colors as it reads on the person's theme; a theme's own key is left to the theme. */
export const toneOf = (color: Color, isLight: boolean): Color => (isLight ? (ON_LIGHT[color] ?? color) : color)

export const MEMBERS: Record<MemberId, Member> = {
  hachiware: {
    id: 'hachiware',
    mark: '🐱',
    role: '지휘',
    speaks: true,
    color: '#4a7fd4',
    ink: '#ffffff',
    line: '#6fa0ea',
  },
  chiikawa: {
    id: 'chiikawa',
    mark: '🐹',
    role: '구현',
    speaks: false,
    color: '#f7a8c0',
    ink: '#000000',
    line: '#f7a8c0',
  },
  usagi: {
    id: 'usagi',
    mark: '🐰',
    role: '탐색',
    speaks: false,
    color: '#f3dc6b',
    ink: '#000000',
    line: '#f3dc6b',
  },
  rakko: {
    id: 'rakko',
    mark: '🦦',
    role: '구현',
    speaks: true,
    color: '#8c7a2e',
    ink: '#ffffff',
    line: '#d8c36a',
  },
  shisa: {
    id: 'shisa',
    mark: '🦁',
    role: '구현',
    speaks: true,
    color: '#f08a24',
    ink: '#000000',
    line: '#f08a24',
  },
  kurimanju: {
    id: 'kurimanju',
    mark: '🌰',
    role: '검토',
    speaks: false,
    color: '#8a5a2b',
    ink: '#ffffff',
    line: '#c08a52',
  },
  kani: {
    id: 'kani',
    mark: '🦀',
    role: '조사',
    speaks: false,
    color: '#e8566a',
    ink: '#ffffff',
    line: '#f29bb0',
  },
  pochette: {
    id: 'pochette',
    mark: '👛',
    role: '구현',
    speaks: true,
    color: '#c9c9c9',
    ink: '#000000',
    line: '#f48fb1',
  },
  momonga: {
    id: 'momonga',
    mark: '🍑',
    role: '검토',
    speaks: true,
    color: '#a8d8f0',
    ink: '#000000',
    line: '#a8d8f0',
  },
  rodo: {
    id: 'rodo',
    mark: '🔔',
    role: '지휘',
    speaks: true,
    color: '#a89f91',
    ink: '#000000',
    line: '#a89f91',
  },
}

export const ORDER: readonly MemberId[] = ['hachiware', 'chiikawa', 'usagi', 'rakko', 'shisa', 'kurimanju', 'kani', 'pochette', 'momonga', 'rodo']
/** The ones who take tasks: 하치와레 conducts, and 노동 갑옷 씨 only rings the bell. */
export const WORKERS: readonly MemberId[] = ['chiikawa', 'usagi', 'rakko', 'shisa', 'kurimanju', 'kani', 'pochette', 'momonga']

export type Situation = 'idle' | 'start' | 'done' | 'fail' | 'slow' | 'denied'

export const MOODS: Record<Situation, Mood> = { idle: 'calm', start: 'calm', done: 'glad', fail: 'sad', slow: 'tired', denied: 'shock' }

const SITUATIONS: readonly Situation[] = ['idle', 'start', 'done', 'fail', 'slow', 'denied']

/** 하치와레's own lines for what he does as the conductor. */
export type Leader = Record<'idle' | 'allDone' | 'sweep' | 'trouble' | 'cry' | 'cheer' | 'sure' | 'found', string>

/**
 * The cast in one language: what each character is called and known for, the
 * work it takes, how it talks and what it says. A language has every part,
 * so one that lacks a line does not load.
 */
export type Cast = {
  names: Record<MemberId, string>
  /** A character's name where there is little room for it, for one whose name is long. */
  short: Partial<Record<MemberId, string>>
  /** The animal the character is drawn after; none where its name already says so. */
  kinds: Record<MemberId, string>
  /** What the character is known for, the reason it gets its kind of work. */
  titles: Record<MemberId, string>
  /** The work it takes, in a few words. */
  jobs: Record<MemberId, string>
  /** What the roles are called on the screen. */
  roles: Record<Role, string>
  /** What the kinds of work are called in the comic's own words. */
  job: Record<Role, string>
  /** The work of a role in a few words, for a character given a role that is not its own. */
  duty: Record<WorkRole, string>
  /** Whose each kind of work is, for the lines that tell of a role changed. */
  specialties: string
  /** A line or a gesture the character has for each occasion; a gesture is in parentheses. */
  quotes: Record<MemberId, Record<Situation, readonly string[]>>
  leader: Leader
  /** His way of reading a friend who cannot talk: "그 말은 ○○라는 거?" with the blank filled. */
  means: (what: string) => string
  /** What the blank is filled with: a task taken, failed, passed, a thing found, a task done, a hand lent to find or to mend. */
  read: Record<'taken' | 'failed' | 'passed' | 'found' | 'done' | 'seeking' | 'mending', string>
  /**
   * Every line a character's voice may use, for the instruction blocks. Each is
   * a line or a sound the character has in the comic; where it was checked
   * against a Japanese source, the original stands beside it.
   */
  lines: Record<MemberId, readonly string[]>
  manner: Record<MemberId, string>
  /** 하치와레 said politely, for a person who would rather be spoken to so. */
  politeLeader: string
}

export const CAST: Record<Lang, Cast> = { en: EN, ko: KO, ja: JA }

/** A character's name where there is little room for it. */
export const shortName = (lang: Lang, id: MemberId): string => CAST[lang].short[id] ?? CAST[lang].names[id]

/** One of the character's own lines for the situation; `turn` rotates them. */
export const say = (lang: Lang, member: MemberId, situation: Situation, turn: number): string => {
  const lines = CAST[lang].quotes[member][situation]

  return lines[Math.abs(turn) % lines.length] ?? lines[0] ?? ''
}

/** Every sound and gesture a character has, as the comic spells it: its lines for each situation, and the ones its voice lists. */
export const soundsOf = (lang: Lang, member: MemberId): string[] => [
  ...Object.values(CAST[lang].quotes[member]).flat(),
  ...CAST[lang].lines[member].flatMap(line => [...line.matchAll(/"([^"]+)"/g)].map(found => found[1] ?? '')),
]

/** A gesture is told, not said: it is drawn without quotation marks. */
export const isGesture = (quote: string): boolean => quote.startsWith('(')

export const shown = (quote: string): string => (isGesture(quote) ? quote : `“${quote}”`)

/** A gesture as what was done, without the parentheses that mark it; a line as it is. */
export const bare = (quote: string): string => quote.replace(/^\((.*)\)$/, '$1')

/**
 * Where the Korean cast has the very sound or gesture the Japanese one has,
 * for the friends who cannot talk: for each occasion, the Korean place of
 * the line at each Japanese place in turn, as far as one is known. The two
 * need not be the same place, as わぁ～…… is the first of its occasion and
 * 와아…… the second. Each was checked by hand, a sound against the original
 * the Korean cast's own list names beside it, a gesture against what it
 * tells. Two lines that only share a place are not here, as 나도! and
 * ヤーッ!!: nothing is made of those. The English cast is the Japanese one put
 * into English place for place, so every place of those two is one line.
 */
const ALIKE: Readonly<Partial<Record<MemberId, Partial<Record<Situation, readonly number[]>>>>> = {
  chiikawa: { start: [0], done: [1], fail: [0], denied: [0, 1] },
  usagi: { idle: [0, 1], start: [0, 1], done: [2, 3], fail: [0], slow: [0] },
  kurimanju: { idle: [0], start: [0], done: [0, 1, 2], fail: [0], slow: [0], denied: [0] },
  kani: { idle: [0, 1], start: [0], done: [0, 1], fail: [0], slow: [0], denied: [0] },
}

/** Each sound and gesture of a character as the languages have it, a Japanese place at a time: the Korean one only where it is that very line. */
const voicesOf = (member: MemberId): Partial<Phrase>[] =>
  SITUATIONS.flatMap(situation =>
    CAST.ja.quotes[member][situation].map((ja, at) => {
      const same = ALIKE[member]?.[situation]?.[at]

      return { ja, en: CAST.en.quotes[member][situation][at], ko: same === undefined ? undefined : CAST.ko.quotes[member][situation][same] }
    }),
  )

/**
 * What a character wrote after its own name as all its report, as each
 * language shows it. It is the worker's own writing and stays as written,
 * but for one case: a character that cannot talk wrote one of its own sounds
 * or gestures, letter for letter, and another language has that very line
 * and no other for it. A gesture written without its parentheses is known by
 * what it tells, and is shown without them. No line is made up: a language
 * with no such line shows the one written.
 */
export const reported = (member: MemberId, line: string): Phrase => {
  if (MEMBERS[member].speaks) return asIs(line)
  const told = (voice: string): string => (isGesture(line) ? voice : bare(voice))
  const known = voicesOf(member).filter(voice => LANGS.some(lang => voice[lang] !== undefined && told(voice[lang]) === line))

  return inAll(lang => {
    const [only, ...others] = new Set(known.flatMap(voice => voice[lang] ?? []))

    return only === undefined || others.length > 0 ? line : told(only)
  })
}

/** How 하치와레 reads what a friend who cannot talk just did. */
export const readingOf = (lang: Lang, member: MemberId, situation: 'start' | 'done' | 'fail', role: Role): string | undefined => {
  const { leader, means, read } = CAST[lang]

  if (MEMBERS[member].speaks) return situation === 'fail' ? leader.trouble : undefined
  if (situation === 'start') return means(read.taken)
  if (situation === 'fail') return member === 'chiikawa' ? leader.cry : means(read.failed)
  if (role === '검토') return means(read.passed)
  if (role === '탐색') return leader.found

  return means(role === '조사' ? read.found : read.done)
}

export const isActive = (task: Task): boolean => task.status === 'running' || task.status === 'waiting'

/** What a task is called on a screen in that language: as it was handed over, but for one the mode named itself. */
export const titleOf = (lang: Lang, task: Pick<Task, 'title' | 'titles'>): string => task.titles?.[lang] ?? task.title

const PREFERENCE: Record<WorkRole, readonly MemberId[]> = {
  구현: ['shisa', 'rakko', 'pochette', 'chiikawa'],
  검토: ['kurimanju', 'momonga', 'rakko'],
  조사: ['kani', 'shisa', 'usagi'],
  탐색: ['usagi', 'kani', 'chiikawa'],
}

/**
 * A test for the English words of a pattern taken whole, so that `format` is
 * not found in `information`, and for the Korean and Japanese ones wherever
 * they stand.
 */
const worded = (english: string, ...others: readonly string[]): RegExp => new RegExp([`(?<![a-z])(?:${english})(?![a-z])`, ...others].join('|'), 'i')

const SPECIALTY: readonly (readonly [RegExp, MemberId])[] = [
  [worded('security|adversarial|agy-review', '반박|보안', 'セキュリティ|反論|脆弱性'), 'momonga'],
  [worded('front-?end|agy-pro|ui|(?:re)?design(?:s|er|ers|ed|ing)?|css', '화면|디자인|스타일', '画面|デザイン|スタイル'), 'pochette'],
  [worded('root-cause|performance|codex-hard|debug(?:s|ged|ger|ging)?', '디버그|디버깅|원인|어려운', 'デバッグ|原因|難しい'), 'rakko'],
  [worded('agy-fast|renam(?:e|es|ed|ing)|(?:re)?format(?:s|ted|ter|ting)?|typos?|clean-?up', '오타|포맷|이름 바꾸|풀 ?뽑기', '誤字|タイポ|フォーマット|リネーム|草むしり'), 'chiikawa'],
]
const SMALL = worded('haiku')

/**
 * The character a kind of work belongs to before its role is weighed: screens
 * to 포쉐트 갑옷 씨, hard bugs to 랏코. Where two fit, the earlier test wins: a
 * security check of a screen is 모몽가's, a screen's bug 포쉐트 갑옷 씨's.
 */
export const specialistOf = (engine: string, title: string, role?: Role): MemberId | undefined => {
  const text = `${engine} ${title}`

  return SPECIALTY.find(([test]) => test.test(text))?.[1] ?? (role === '구현' && SMALL.test(text) ? 'chiikawa' : undefined)
}

export const WORK_ROLES: readonly WorkRole[] = ['구현', '검토', '조사', '탐색']

/** The role a character has: the one the person gave it, or its own. */
export const roleOf = (id: MemberId, roles: Roles = {}): Role => roles[id] ?? MEMBERS[id].role

/** The work a character takes, in a few words: its own, or that of the role the person gave it. */
export const jobOf = (lang: Lang, id: MemberId, roles: Roles = {}): string => {
  const given = roles[id]

  return given === undefined ? CAST[lang].jobs[id] : CAST[lang].duty[given]
}

/** The roles with one character's set: its own role, or none, is no change kept, and only one who takes tasks has a role to change. */
export const withRole = (roles: Roles, id: MemberId, role: WorkRole | null): Roles => {
  const rest: Roles = Object.fromEntries(Object.entries(roles).filter(([key]) => key !== id))

  return role === null || role === MEMBERS[id].role || !WORKERS.includes(id) ? rest : { ...rest, [id]: role }
}

/** The roles an earlier session kept, with whatever is not a role of one who takes tasks left out. */
export const rolesFrom = (kept: unknown): Roles => {
  if (typeof kept !== 'object' || kept === null) return {}
  const held: Readonly<Record<string, unknown>> = { ...kept }

  return WORKERS.reduce<Roles>((roles, id) => {
    const role = WORK_ROLES.find(one => one === held[id])

    return role === undefined ? roles : withRole(roles, id, role)
  }, {})
}

/**
 * The specialist, or the role's own character, or while that one is busy the
 * next with free hands. A specialty is a kind of work, so its character comes
 * before one the person gave the role; that one comes before those whose own
 * the role is; one given another role leaves this one, and its specialty too.
 */
export const pickMember = (role: Role, tasks: readonly Task[], specialist?: MemberId, roles: Roles = {}): MemberId => {
  const wanted = role === '지휘' ? '구현' : role
  const given = WORKERS.filter(id => roles[id] === wanted)
  const stayed = PREFERENCE[wanted].filter(id => roles[id] === undefined)
  const own = given.length + stayed.length > 0 ? [...given, ...stayed] : PREFERENCE[wanted]
  const first = specialist !== undefined && roles[specialist] === undefined ? specialist : undefined
  const order = first === undefined ? own : [first, ...own.filter(id => id !== first)]
  const free = order.find(id => !tasks.some(task => task.member === id && isActive(task)))

  return free ?? order[0] ?? 'shisa'
}

// A kind that looks things up is not one that finds a place, whatever else its name holds: the first test that fits wins.
const TYPE_ROLES: readonly (readonly [RegExp, Role])[] = [
  [worded('research(?:er)?|writer|document(?:s|er|ation)?|requirements?|learning|mentor|plan(?:ner|ning)?'), '조사'],
  [worded('explorer?|scout|search(?:er)?|guide'), '탐색'],
  [worded('review(?:er)?|security|quality|audit(?:or)?|test(?:s|er|ing)?|root-cause|analy(?:st|sis|ze|zer|tics)'), '검토'],
  [worded('architect|engineer|expert|refactor(?:ing)?'), '구현'],
]
const WORK_WORDS: readonly (readonly [RegExp, Role])[] = [
  [worded('review(?:s|ed|er|ing)?|verif(?:y|ies|ied|ication)|audit(?:s|ed|ing)?', '검토|리뷰|검증|다시 보', 'レビュー|検証|見直'), '검토'],
  [worded('explor(?:e|es|ed|ing)|locat(?:e|es|ed|ing)|find(?:s|ing)?', '탐색|찾|위치', '探索|探す|さがす|場所'), '탐색'],
  [worded('research(?:es|ed|ing)?|document(?:s|ed|ing|ation)?|summar(?:y|ies|ize|izes|ized|izing)', '조사|정리|문서', '調査|整理|文書|ドキュメント|まとめ'), '조사'],
  [worded('implement(?:s|ed|ing|ation)?|fix(?:es|ed|ing)?|(?:re)?build(?:s|ing)?|(?:re)?writ(?:e|es|ing)', '구현|수정|고치|작성|만들|토벌', '実装|修正|直す|作成|作る|討伐'), '구현'],
]

/** The role an agent type or a description tells, when one does. */
export const roleOfAgent = (subagentType: string, description: string): Role | undefined =>
  (TYPE_ROLES.find(([test]) => test.test(subagentType)) ?? WORK_WORDS.find(([test]) => test.test(description)))?.[1]

export const PROFILES: Record<string, Role> = {
  'codex-build': '구현',
  'codex-hard': '구현',
  'codex-scout': '탐색',
  'grok-research': '조사',
  'grok-build': '구현',
  'agy-fast': '구현',
  'agy-pro': '구현',
  'agy-review': '검토',
  'claude-build': '구현',
  'claude-review': '검토',
}

files.hooks/orca.ts:
// Reads `fleet-run <profile> --spec <file> --out <file>` out of a shell
// command: the Orca worker launches the conductor makes through Bash.
//
// The command is read the way a shell reads it, as far as that is plain: a
// statement at a time, word by word, its quotes, comments and here-documents
// told apart. A launch counts only where the shell is sure to run it, and a
// path only where what it comes to is sure: written out, or made of
// variables this very command assigned as plain text, with nothing run since
// that may have assigned them again. What is sure is told narrowly, the same
// for bash, zsh and sh, and anything else is left out, so that nothing is
// tracked or written over on a guess.

import type { Tokens } from '../types'

import type { Words } from './words'

export type FleetRun = {
  profile: string
  /**
   * Where in the command the spec's path stands, without its quotes: from,
   * and up to. Only with `spec`, and only where another path can be written
   * there.
   */
  specSpan?: readonly [number, number]
  /** The paths with the command's own variables filled in, when plain. */
  spec?: string
  out?: string
  title: string
  /** Whether `--out` was given at all: given and not here, its path could not be read. */
  hasOut: boolean
  /** An `&` closes its command: the shell does not wait for it. */
  isBackground: boolean
  /** It is handed to something that answers at once, an Orca terminal or `nohup`: the command does not wait for it either. */
  isDetached: boolean
}

/**
 * A stretch of a word read one way: bare, inside one kind of quotes, or a
 * command run to make it, `$(…)` or `<(…)`. Its place is its text's, without
 * the quotes or the parentheses.
 */
type Piece = { text: string; quote: '' | '"' | "'" | '('; from: number; to: number }
/** A word of a command, and its place with its quotes. One that runs into a `<` with no space between is cut: what it comes to is not told. */
type Word = { pieces: Piece[]; from: number; to: number; isCut?: boolean }
/** One command of a script: its words, and the operators it stands between. One that is odd holds something not read here as the shell reads it. */
type Statement = { words: Word[]; before: string; after: string; isOdd: boolean }
/** What the variables assigned so far are sure to hold. */
type Vars = Map<string, string>
/** A script a command hands a shell in quotes, as that shell reads it, and where in the command each character of it was written. */
type Script = { text: string; from: number[]; to: number[] }
/** What is sure of the shell at one point of a script. */
type Shell = {
  /** The variables, the home directory among them as `HOME`. */
  vars: Vars
  /** The variables made read-only: assigning one again does not go as written. */
  sealed: Set<string>
  /** Whether what a variable written bare holds stays one word: nothing so far may have changed where the shell parts it. */
  isWhole: boolean
  /** Nothing is sure from here on: something was met that this does not follow. */
  isLost: boolean
}

/** A path that goes into a command as it is, with nothing for a shell to read into it: letters and digits of any script, and the few signs a path is written with. */
const PLAIN = /^[\p{L}\p{N}\p{M}_@%+=:,./~-]+$/u
/** Such a path with spaces in it, which only quotes hold together. */
const SPACED = /^[\p{L}\p{N}\p{M}_@%+=:,./~ -]+$/u
/** What parts two words for the shell: no other space does, however much it looks like one. */
const BLANK = /^[ \t]$/
const BARE = /[^ \t\n\\'"`;&|()<>]+/y
const OPERATOR = /;;|&&|\|\||\|&|[;&|()`]/y
const REDIRECT = /&>>?|[<>][<>&|]*/y
const HERE = /<<(-?)[ \t]*(?:'([^'\n]*)'|"([^"\n]*)"|\\?([^\s\\'"`;&|()<>]+))/y
/** What stands right before a redirection as a part of it: the number of what is redirected, or the variable it is kept in. */
const REDIRECTED = /^(?:\d+|\{\w+\})$/
const ASSIGNED = /^([A-Za-z_]\w*)(\+?)=/
const NAME = /^[A-Za-z_]\w*$/
const FUNCTION_NAME = /^[A-Za-z_][\w.:-]*$/
/** A command's name written out: a program's, with its path or not, or a builtin's. */
const COMMAND = /^(?:[:[]|[\p{L}\p{N}_./~][\p{L}\p{N}_.+/-]*)$/u
/**
 * What the shell fills in with more than a variable holds, or what is not
 * read here as the shell reads it: a `${…}` that is not a name alone or a
 * name with a plain default or a plain cut, arithmetic, a subscript, a
 * backquote.
 */
const ODD = /\$\{(?!#?[A-Za-z_]\w*(?:(?::?[-+]|%%?|##?)[\w./*?-]*)?\})|\$\(\(|\$\[|\$\w+\[|`/
/** In a command run to make a word, what hides where it ends: a here-document, a `case`, a quote of another kind. */
const KNOTTY = /<<|\besac\b|\$['"]/
/** What `set` is given to stop at an error or to show what is run: nothing a word is read by. */
const SET = /^(?:[-+][euvx]*o?|errexit|nounset|pipefail|verbose|xtrace)$/
/** After a variable written bare with no braces, what is sure to be no part of its name, a modifier or a subscript, in quotes and out of them. */
const AFTER = { '': /^[/.-]?$/, '"': /^[^:[\p{L}\p{N}\p{M}]?$/u } as const

/** The character at a place of a text, whole where it is written as two units; none past the end. */
const charAt = (text: string, at: number): string => {
  const point = text.codePointAt(at)

  return point === undefined ? '' : String.fromCodePoint(point)
}

/** Reserved words a command may stand behind, and how each moves the count of the blocks around it. */
const KEYWORDS = new Map<string, number>([
  ['if', 1],
  ['case', 1],
  ['while', 1],
  ['until', 1],
  ['for', 1],
  ['select', 1],
  ['{', 1],
  ['fi', -1],
  ['esac', -1],
  ['done', -1],
  ['}', -1],
  ['then', 0],
  ['do', 0],
  ['else', 0],
  ['elif', 0],
  ['!', 0],
  ['time', 0],
])
const LOOPS = new Set(['while', 'until', 'for', 'select'])
/** Commands that run the command named after them. */
const WRAPPERS = new Set(['nohup', 'exec', 'command', 'env'])
/** Commands whose arguments assign, where the shell has them: only where they stand alone, with no option, is no more than that done. */
const DECLARES = new Set(['declare', 'typeset', 'local'])
/** Every builtin whose arguments assign. Behind a word that runs the command named after it, none is sure to be the shell's own. */
const ASSIGNERS = new Set(['export', 'readonly', ...DECLARES])
/** Builtins that assign variables and do no more: nothing known before one is sure after it. */
const WRITERS = new Set(['read', 'unset', 'getopts', 'mapfile', 'readarray', 'let', 'shift', 'print', 'getln', 'set'])
/** Builtins given a count, which zsh reads as arithmetic. */
const COUNTED = new Set(['break', 'continue', 'exit', 'return'])
/** What `printf` is told to print with no option and no number in it: text, `%s`, `%b` and `%q`. */
const FORMAT = /^(?!-)(?:[^%]|%%|%[-0-9.]*[sbq])*$/
/** What `test` is given that some shell reads a word after it as arithmetic for. */
const TESTED = /^-(?:[tvR]|eq|ne|lt|le|gt|ge)$/
/**
 * Every other word bash, zsh and sh keep for themselves that may change the
 * shell: its variables' kinds, its options, what a name runs. Past one,
 * nothing is sure. A builtin in none of these lists changes no variable, and
 * neither does a program.
 */
const SHELL_WORDS = new Set(
  (
    '. alias autoload bg bind bindkey builtin bye caller compadd comparguments compcall compctl compdescribe compfiles compgen compgroups complete compopt compquote compset comptags comptry compvalues ' +
    'coproc disable echotc echoti emulate enable end eval fc fg float foreach function functions help history integer limit log logout nocorrect noglob private pushln r rehash repeat sched setopt shopt ' +
    'source suspend trap ttyctl unalias unfunction unhash unlimit unsetopt vared zcompile zformat zle zmodload zparseopts zregexparse zstyle'
  ).split(' '),
)
/** Variables the shells keep for themselves, by how their names begin and by name: what one holds is the shell's to change, and is never taken as known. */
const SPECIAL = new RegExp(
  `^(?:(?:BASH|ZSH_|zsh_|COMP_|READLINE_|ZLE_|dis_|EPOCH|LC_)\\w*|${(
    '_ ARGC BAUD CDPATH CHILD_MAX COLUMNS COPROC CPUTYPE DIRSTACK DIRSTACKSIZE EGID EMACS ENV ERRNO EUID EXECIGNORE FCEDIT FIGNORE FPATH FUNCNAME FUNCNEST GID GLOBIGNORE GROUPS HISTCHARS HISTCMD HISTCONTROL ' +
    'HISTFILE HISTFILESIZE HISTIGNORE HISTSIZE HISTTIMEFORMAT HOST HOSTFILE HOSTNAME HOSTTYPE IFS IGNOREEOF INPUTRC INSIDE_EMACS KEYBOARD_HACK KEYTIMEOUT LANG LINENO LINES LISTMAX LOGCHECK LOGNAME MACHTYPE MAIL ' +
    'MAILCHECK MAILPATH MANPATH MAPFILE MATCH MBEGIN MEND MODULE_PATH NULLCMD OLDPWD OPTARG OPTERR OPTIND OSTYPE PATH PERIOD PIPESTATUS POSIXLY_CORRECT POSTEDIT PPID PROMPT PROMPT2 PROMPT3 PROMPT4 PROMPT_COMMAND ' +
    'PROMPT_DIRTRIM PS0 PS1 PS2 PS3 PS4 PSVAR PWD RANDOM READNULLCMD REPLY REPORTMEMORY REPORTTIME RPROMPT RPROMPT2 RPS1 RPS2 SAVEHIST SECONDS SHELL SHELLOPTS SHLVL SPROMPT SRANDOM STTY TERM TERMINFO TIMEFMT ' +
    'TIMEFORMAT TMOUT TMPPREFIX TMPSUFFIX TRY_BLOCK_ERROR TRY_BLOCK_INTERRUPT TTY TTYIDLE UID USERNAME VENDOR WATCH WATCHFMT WORDCHARS ZBEEP ZDOTDIR aliases argv auto_resume builtins cdpath commands dirstack ' +
    'epochtime errnos fignore fpath funcfiletrace funcsourcetrace funcstack functions functions_source functrace galiases histchars history historywords jobdirs jobstates jobtexts keymaps langinfo mailpath manpath ' +
    'mapfile match mbegin mend module_path modules nameddirs options parameters patchars path pipestatus prompt psvar reply reswords saliases signals status sysparams termcap terminfo userdirs usergroups watch widgets'
  ).replace(/ /g, '|')})$`,
)
/** Those of them a shell is ruled by: one assigned, the shell may read what follows another way, or run what it holds as it shows each command. */
const RULING = new Set(['POSIXLY_CORRECT', 'BASH_COMPAT', 'BASH_ENV', 'BASHOPTS', 'SHELLOPTS', 'ENV', 'ZDOTDIR', 'HISTCHARS', 'histchars', 'NULLCMD', 'READNULLCMD', 'PS4', 'PROMPT4'])
const SHELLS = new Set(['bash', 'zsh', 'sh'])
/** After one of these a statement runs only if the one before it went a certain way, or in a shell of its own. */
const CONDITIONAL = new Set(['&&', '||', '|', '|&'])
/** Before one of these a statement runs in a shell of its own. */
const UNWAITED = new Set(['&', '|', '|&'])

const found = (pattern: RegExp, text: string, at: number): RegExpExecArray | null => {
  pattern.lastIndex = at

  return pattern.exec(text)
}

/** Where the parenthesis opened before `at` closes, the quotes and the comments inside it passed over; -1 where it does not. */
const parenEnd = (text: string, at: number): number => {
  let depth = 1

  for (let end = at; end < text.length; end += 1) {
    const char = text[end]

    if (char === '\\') end += 1
    else if (char === "'") end = text.indexOf("'", end + 1)
    else if (char === '"') end = quoteEnd(text, end + 1)
    else if (char === '#' && /^[\s;&|()]$/.test(text[end - 1] ?? '')) end = text.indexOf('\n', end)
    else if (char === '(') depth += 1
    else if (char === ')' && (depth -= 1) === 0) return end
    if (end < 0) return -1
  }

  return -1
}

/** Where the double quote opened before `at` closes, the commands it holds passed over; -1 where it does not. */
const quoteEnd = (text: string, at: number): number => {
  for (let end = at; end < text.length; end += 1) {
    const char = text[end]

    if (char === '"') return end
    if (char === '\\') end += 1
    else if (char === '`') end = text.indexOf('`', end + 1)
    else if (char === '$' && text[end + 1] === '(') end = parenEnd(text, end + 2)
    if (end < 0) return -1
  }

  return -1
}

/** Whether a stretch of a word holds something not read here as the shell reads it. */
const isOddPiece = ({ text, quote }: Piece): boolean => quote !== "'" && (ODD.test(text) || ((quote === '(' || text.includes('$(')) && KNOTTY.test(text)))

/**
 * A script as its commands, in the order written. A comment and the lines
 * of a here-document are no part of any, and neither is a redirection: its
 * sign, the number before it and the word it leads to are none of the
 * command's words, wherever among them they stand. A command run to make a
 * word, `$(…)` or `<(…)`, is a piece of that word. Undefined where a quote
 * or such a command is left open: nothing after it can be told.
 */
const statementsOf = (text: string): Statement[] | undefined => {
  const statements: Statement[] = []
  /** The here-documents opened on this line: the line that closes each, whether tabs before it are dropped, whether the shell fills its lines in, and the statement it is of. */
  const waiting: { mark: string; isIndented: boolean; isFilled: boolean; owner: number }[] = []
  let words: Word[] = []
  let word: Word | undefined
  let before = ''
  let at = 0
  /** Whether the next word is what a redirection leads to. */
  let isTarget = false
  /** Whether the statement being read holds something not read here as the shell reads it. */
  let isOdd = false
  const add = (piece: Piece, from: number, to: number): void => {
    word ??= { pieces: [], from, to }
    word.pieces.push(piece)
    word.to = to
    isOdd ||= isOddPiece(piece)
  }
  /** Ends the word being read, and with an operator the statement. */
  const close = (after?: string): void => {
    if (word !== undefined && !isTarget) words.push(word)
    if (word !== undefined || after !== undefined) isTarget = false
    word = undefined
    if (after === undefined) return
    statements.push({ words, before, after, isOdd })
    words = []
    before = after
    isOdd = false
  }
  /** Takes the command run to make a part of the word being read, whose parenthesis opens at `open`. Answers whether it closes. */
  const run = (open: number, from: number): boolean => {
    const end = parenEnd(text, open + 1)

    if (end >= 0) add({ text: text.slice(open + 1, end), quote: '(', from: open + 1, to: end }, from, end + 1)
    at = end + 1

    return end >= 0
  }

  while (at < text.length) {
    const char = text[at] ?? ''
    const last = word?.pieces.at(-1)
    /** Whether a `$` written bare stands right before this character. */
    const isDollared = last?.quote === '' && last.text.endsWith('$')

    if (char === '\\') {
      // A backslash keeps the next character as it is written; at a line's end it joins the next line on.
      if (text[at + 1] !== '\n') add({ text: text[at + 1] ?? '', quote: "'", from: at, to: at + 2 }, at, at + 2)
      at += 2
    } else if (char === "'" || char === '"') {
      const end = char === "'" ? text.indexOf("'", at + 1) : quoteEnd(text, at + 1)

      if (end < 0) return undefined
      // `$'…'` and `$"…"` are quotes of another kind, and a quote that runs over a line's end moves where a here-document begins.
      if (isDollared || (waiting.length > 0 && text.slice(at, end).includes('\n'))) isOdd = true
      add({ text: text.slice(at + 1, end), quote: char, from: at + 1, to: end }, at, end + 1)
      at = end + 1
    } else if (char === '\n') {
      close('\n')
      at += 1
      for (const { mark, isIndented, isFilled, owner } of waiting.splice(0)) {
        const from = at
        const opened = statements[owner]

        while (at < text.length) {
          const end = text.indexOf('\n', at)
          const line = text.slice(at, end < 0 ? text.length : end)

          at = end < 0 ? text.length : end + 1
          if ((isIndented ? line.replace(/^\t+/, '') : line) === mark) break
        }
        if (isFilled && opened !== undefined && ODD.test(text.slice(from, at))) opened.isOdd = true
      }
    } else if (BLANK.test(char)) {
      close()
      at += 1
    } else if (char === '#' && word === undefined) {
      const end = text.indexOf('\n', at)

      // Right after a parenthesis, zsh reads it as a part of a pattern.
      if (text[at - 1] === '(') isOdd = true
      at = end < 0 ? text.length : end
    } else if ((char === '(' && isDollared) || ((char === '<' || char === '>') && text[at + 1] === '(')) {
      // `$((…))` is arithmetic, which may assign.
      if (text[at + 1] === '(' && char === '(') isOdd = true
      if (!run(char === '(' ? at : at + 1, at)) return undefined
    } else {
      const here = found(HERE, text, at)
      const sign = here ?? found(REDIRECT, text, at)
      const operator = sign ?? found(OPERATOR, text, at)
      const bare = operator ?? found(BARE, text, at)

      if (here !== null) {
        waiting.push({ mark: here[2] ?? here[3] ?? here[4] ?? '', isIndented: here[1] === '-', isFilled: here[4] !== undefined && !here[0].includes('\\'), owner: statements.length })
        // A closing line written partly in quotes is not the one read here.
        if (/^[^\s;&|()<>]$/.test(text[at + here[0].length] ?? '')) isOdd = true
      }
      // A redirection parts two words, and an operator ends the statement.
      if (sign !== null) {
        if (word !== undefined && REDIRECTED.test(bareOf(word) ?? '')) {
          // `{name}>` assigns the variable the number of what it opens.
          if (bareOf(word)?.startsWith('{') === true) isOdd = true
          word = undefined
        }
        // `<1-9>` right after a word is a part of a pattern to zsh.
        else if (word !== undefined && sign[0].startsWith('<')) word.isCut = true
        close()
        // A here-document's sign has its closing line with it; any other leads to the word after it.
        isTarget = here === null
        // `>!` is one sign to zsh, and a file named `!` to the others.
        if (text[at + sign[0].length] === '!') isOdd = true
      } else if (operator !== null) {
        // A backquote, arithmetic, and a parenthesis that goes on a word, as an array's or a pattern's does, are not followed; a function's own `()` is.
        if (operator[0] === '`' || (operator[0] === '(' && (text[at + 1] === '(' || (word !== undefined && !/^[ \t]*\)/.test(text.slice(at + 1)))))) isOdd = true
        close(operator[0])
      } else if (bare !== null) add({ text: bare[0], quote: '', from: at, to: at + bare[0].length }, at, at + bare[0].length)
      at += bare?.[0].length ?? 1
    }
  }
  close('')

  return statements
}

/** A word written bare with nothing for the shell to fill in: an option, a keyword, a profile. */
const bareOf = (word: Word | undefined): string | undefined => {
  const [piece, ...more] = word?.pieces ?? []

  return piece !== undefined && more.length === 0 && piece.quote === '' && !piece.text.includes('$') ? piece.text : undefined
}

/** A word the shell hands on as it is written, in quotes or not, with nothing to fill in: a profile, an option. */
const literalOf = (word: Word | undefined): string | undefined => {
  const pieces = word?.pieces ?? []
  const isFilled = pieces.some(piece => piece.quote === '(' || (piece.quote !== "'" && /[$`\\]/.test(piece.text)))

  return pieces.length === 0 || isFilled || word?.isCut === true ? undefined : pieces.map(piece => piece.text).join('')
}

/** The command a word names: the last part of its path, where that part is written out. */
const nameOf = (word: Word | undefined): string | undefined => {
  const pieces = word?.pieces ?? []
  const text = pieces.map(piece => piece.text).join('')
  const name = text.slice(text.lastIndexOf('/') + 1)

  return word === undefined || pieces.some(piece => piece.quote === '(') || /[$`\\]/.test(name) ? undefined : name
}

/** What a word assigns, where it is an assignment: `NAME=` at its start, written bare. */
const assigned = (word: Word | undefined): RegExpExecArray | null => {
  const first = word?.pieces[0]

  return first?.quote === '' ? ASSIGNED.exec(first.text) : null
}

/** A word from so many characters into its first piece: what follows `NAME=` or `--option=`. */
const rest = (word: Word, skip: number): Word => {
  const [first, ...more] = word.pieces

  if (first === undefined) return word
  const from = first.from + skip
  const head = { ...first, text: first.text.slice(skip), from }

  return { ...word, pieces: head.text === '' ? more : [head, ...more], from }
}

/**
 * What a word comes to once the shell has filled it in, where that is sure
 * and plain: single quotes keep what they hold, a variable is one assigned
 * earlier, and `~/` opening a bare word is the home directory. A space is
 * plain only in a word that is one stretch in quotes: there the shell does
 * not part what a variable holds, and a path written in its place stays
 * inside the quotes.
 *
 * A variable is followed only as `$NAME` or `${NAME}`, and `$NAME` only
 * before what no shell takes for more of the name, a modifier or a
 * subscript. Bare, where the shell may part what it holds, it is followed
 * only while nothing may have changed how: `isParted` is off for an
 * assignment's own value, which no shell parts. A `~` anywhere else and an
 * `=` that opens a word are filled in by some shell, and are not followed.
 */
const resolve = (word: Word, shell: Shell, isTildeRead = true, isParted = true): string | undefined => {
  const home = shell.vars.get('HOME')
  let isSure = !shell.isLost && word.isCut !== true
  const text = word.pieces
    .map((piece, index) => {
      const { text: written, quote } = piece

      if (quote === "'") return written
      if (quote === '(') {
        isSure = false

        return ''
      }
      const filled = written.replace(/\$\{(\w+)\}|\$(\w+)|\$/g, (whole, braced: string | undefined, bare: string | undefined, at: number) => {
        const value = shell.vars.get(braced ?? bare ?? '')
        const isJoined = bare !== undefined && !AFTER[quote].test(charAt(written, at + whole.length))

        if (value === undefined || isJoined || (quote === '' && isParted && !shell.isWhole)) isSure = false

        return value ?? ''
      })

      if (quote === '"' || !/^=|~/.test(written)) return filled
      if (index > 0 || !isTildeRead || home === undefined || !/^~\/[^~]*$/.test(written)) isSure = false

      return `${home ?? ''}${filled.slice(1)}`
    })
    .join('')

  const [only, ...more] = word.pieces
  const isHeld = only !== undefined && more.length === 0 && only.quote !== ''

  return isSure && (isHeld ? SPACED : PLAIN).test(text) && !/^[~=]/.test(text) ? text : undefined
}

/** Leaves nothing known of the variables: any of them may have been assigned. */
const forget = (shell: Shell): void => shell.vars.clear()

/** Leaves nothing sure from here on. */
const lose = (shell: Shell): void => {
  shell.isLost = true
  shell.vars.clear()
}

/** Leaves the variables some words assign unknown. One the shell is ruled by, or one that is read-only, leaves nothing sure. */
const strike = (words: readonly Word[], shell: Shell): void => {
  for (const word of words) {
    const name = assigned(word)?.[1] ?? bareOf(word) ?? ''

    shell.vars.delete(name)
    if (shell.sealed.has(name) || RULING.has(name)) lose(shell)
  }
}

/**
 * Takes the assignments the shell is sure to make: one of plain text is
 * kept, and one that is not (appended to, not plain, or of a variable the
 * shells keep for themselves) leaves its variable unknown. `known` is what
 * their own variables are read from.
 */
const assign = (words: readonly Word[], shell: Shell, known: Vars, isParted: boolean): void => {
  for (const word of words) {
    const [whole, name, plus] = assigned(word) ?? []

    if (whole === undefined || name === undefined) continue
    const value = plus === '' && !SPECIAL.test(name) ? resolve(rest(word, whole.length), { ...shell, vars: known }, true, isParted) : undefined

    strike([word], shell)
    if (value !== undefined && !shell.isLost) shell.vars.set(name, value)
  }
}

/** The value an option is given, as the next word or after `=` in its own; none where it is given twice or not at all. */
const valueOf = (args: readonly Word[], name: string): { word: Word; isApart: boolean } | undefined => {
  const flag = `--${name}`
  const given = args.flatMap((word, index) => {
    const next = args[index + 1]
    const first = word.pieces[0]

    if (literalOf(word) === flag) return next === undefined ? [] : [{ word: next, isApart: true }]

    return first?.quote === '' && first.text.startsWith(`${flag}=`) ? [{ word: rest(word, flag.length + 1), isApart: false }] : []
  })

  return given.length === 1 ? given[0] : undefined
}

const baseName = (path: string): string => path.slice(path.lastIndexOf('/') + 1)

/** The launch a `fleet-run`'s arguments make, its paths as far as they are sure; none where no profile is named. */
const runOf = (args: readonly Word[], shell: Shell, isBackground: boolean, isDetached: boolean): FleetRun | undefined => {
  const profile = literalOf(args[0])

  if (profile === undefined || !/^[a-z]+-[a-z]+$/.test(profile)) return undefined
  const given = valueOf(args, 'spec')
  const kept = valueOf(args, 'out')
  // A `~` after `--spec=` is not the home directory: only one that opens a word is.
  const spec = given === undefined ? undefined : resolve(given.word, shell, given.isApart)
  const out = kept === undefined ? undefined : resolve(kept.word, shell, kept.isApart)
  const named = baseName(spec ?? out ?? '').replace(/\.(?:spec|out)\.md$|\.md$/, '')
  const run: FleetRun = { profile, title: named === '' ? profile : named, hasOut: kept !== undefined, isBackground, isDetached }

  if (given !== undefined && spec !== undefined) {
    const [piece, ...more] = given.word.pieces

    run.spec = spec
    // One piece is written over inside its quotes; a word of several, quotes and all.
    run.specSpan = piece !== undefined && more.length === 0 ? [piece.from, piece.to] : [given.word.from, given.word.to]
  }
  if (out !== undefined) run.out = out

  return run
}

/**
 * The word a command hands a shell to run: `orca terminal create --command
 * <word>`, `sh -c <word>`. A shell given any option before its `-c` may read
 * the word another way: it is not plain.
 */
const handedOf = (name: string | undefined, args: readonly Word[]): { word: Word; isPlain: boolean } | undefined => {
  const command = name === 'orca' && bareOf(args[0]) === 'terminal' && bareOf(args[1]) === 'create' ? valueOf(args, 'command')?.word : undefined

  if (command !== undefined) return { word: command, isPlain: true }
  if (name === undefined || !SHELLS.has(name)) return undefined
  for (const [index, arg] of args.entries()) {
    const flag = bareOf(arg)
    const word = args[index + 1]

    if (flag === '-c' || flag === '-lc') return word === undefined ? undefined : { word, isPlain: index === 0 }
    if (flag === undefined || !flag.startsWith('-')) return undefined
  }

  return undefined
}

/**
 * A handed word as the script the shell it is handed to reads. Only a word
 * that is one quoted stretch is read, and not one that runs a command to
 * make its text. Double quotes are filled in before the script is handed
 * on: an escape gives its character, a variable what it holds, and one not
 * known a character no path has. So does one that holds a space, where the
 * shell it is handed to parts it, and anything else a `$` opens.
 */
const scriptOf = (word: Word, shell: Shell): Script | undefined => {
  const [piece, ...more] = word.pieces
  const script: Script = { text: '', from: [], to: [] }

  if (piece === undefined || more.length > 0 || piece.quote === '' || piece.quote === '(' || (piece.quote === '"' && /`|\$\(/.test(piece.text))) return undefined
  const { text: written } = piece
  let at = piece.from

  for (const { 0: whole, 1: escaped, 2: braced, 3: bare, index } of written.matchAll(piece.quote === '"' ? /\\([\s\S])|\$\{(\w+)\}|\$(\w+)|[\s\S]/g : /[\s\S]/g)) {
    const held = shell.vars.get(braced ?? bare ?? '')
    const isJoined = bare !== undefined && !AFTER['"'].test(charAt(written, index + whole.length))
    const filled = held === undefined || held.includes(' ') || isJoined ? '\0' : held
    const text = escaped !== undefined ? (escaped === '\n' ? '' : '"\\$`'.includes(escaped) ? escaped : whole) : piece.quote === '"' && whole.startsWith('$') ? filled : whole

    script.text += text
    for (let unit = 0; unit < text.length; unit += 1) {
      script.from.push(at)
      script.to.push(at + whole.length)
    }
    at += whole.length
  }

  return script
}

/**
 * A run found in a script handed on, with its spec's place given in the
 * command the script stands in. A place that begins or ends partway through
 * what a variable was filled with is not one to write a path into: the run
 * then has none.
 */
const placed = (run: FleetRun, script: Script, isBackground: boolean, isDetached: boolean): FleetRun => {
  const { specSpan, ...more } = run
  const moved = { ...more, isBackground: run.isBackground || isBackground, isDetached: run.isDetached || isDetached }
  const from = specSpan === undefined ? undefined : script.from[specSpan[0]]
  const to = specSpan === undefined ? undefined : script.to[specSpan[1] - 1]

  if (specSpan === undefined || from === undefined || to === undefined || from === script.from[specSpan[0] - 1] || to === script.to[specSpan[1]]) return moved

  return { ...moved, specSpan: [from, to] }
}

/**
 * How many words of a statement open a function's definition: `name` before
 * its own `()`, or `function name`. The compound command that comes next is
 * the function's body.
 */
const definedAt = (statements: readonly Statement[], index: number): number | undefined => {
  const { words = [], after = '' } = statements[index] ?? {}
  const next = statements[index + 1]
  const first = bareOf(words[0])
  const second = bareOf(words[1])

  if (first === 'function' && second !== undefined && FUNCTION_NAME.test(second)) return 2
  const isNamed = words.length === 1 && after === '(' && next !== undefined && next.words.length === 0 && next.after === ')'

  return isNamed && first !== undefined && FUNCTION_NAME.test(first) && !KEYWORDS.has(first) ? 1 : undefined
}

/**
 * Whether the list a statement is of may run in a shell of its own:
 * `a && b &` runs both in one. Where a list ends is not followed past a
 * block or a parenthesis.
 */
const isApart = (statements: readonly Statement[], index: number): boolean => {
  let at = index

  while (CONDITIONAL.has(statements[at]?.after ?? '')) {
    at += 1
    if (KEYWORDS.has(bareOf(statements[at]?.words[0]) ?? '')) return true
  }

  return /^[&(]$/.test(statements[at]?.after ?? '')
}

/**
 * Whether a builtin that changes no variable by itself is sure to change
 * none as it is given here. `printf -v` and `wait -p` assign. zsh reads as
 * arithmetic, which may assign, what `printf` prints as a number, what a
 * loop or the shell is left with, and what `test -t` is given; a newer bash
 * reads so the subscript of what `test -v` names, and a Korn shell what
 * `test` compares as numbers.
 */
const isTame = (name: string, args: readonly Word[], shell: Shell): boolean => {
  /** Whether a word is sure to open with no `-`, whatever it is filled in with: it is no option. */
  const isGiven = (arg: Word): boolean => arg.pieces[0]?.quote !== '(' && /^[^-$`\\]/.test(arg.pieces[0]?.text ?? '')
  const [format] = args

  if (name === 'printf') return format?.pieces.every(piece => piece.quote === "'" || (piece.quote !== '(' && !/[$`]/.test(piece.text))) === true && FORMAT.test(format.pieces.map(piece => piece.text).join(''))
  if (name === 'wait') return args.every(isGiven)
  if (COUNTED.has(name)) return args.every(arg => /^\d+$/.test(literalOf(arg) ?? ''))
  if (name === 'test' || name === '[') return args.every(arg => !TESTED.test(literalOf(arg) ?? resolve(arg, shell) ?? '-t'))

  return !WRITERS.has(name) && !DECLARES.has(name)
}

/**
 * Takes what a command may have done to the shell it ran in. A program, and
 * a builtin that only prints, tests or moves about, changes no variable.
 * `export` and `readonly` with nothing but names and assignments assign as
 * a statement of assignments does, where the shell is sure to run them. A
 * builtin that assigns, or that may as it is given here, leaves no variable
 * known. Anything else the shells keep for themselves, and a name not
 * written out, leave nothing sure.
 */
const affect = (word: Word | undefined, args: readonly Word[], shell: Shell, isRun: boolean): void => {
  const name = bareOf(word) ?? ''
  const isNamed = args.every(arg => assigned(arg) !== null || NAME.test(bareOf(arg) ?? ''))
  const isWritten = args.every(arg => literalOf(arg) !== undefined)

  if (!COMMAND.test(name) || SHELL_WORDS.has(name)) return lose(shell)
  // A name with a path in it is a program's.
  if (name.includes('/')) return
  if (name === 'export' || name === 'readonly') {
    // An option makes it more than an assignment, and a variable that may or may not have been made read-only is not one to assign again.
    if (!isNamed || (name === 'readonly' && !isRun)) return lose(shell)
    if (isRun) assign(args, shell, new Map(shell.vars), true)
    else {
      strike(args, shell)
      forget(shell)
    }
    if (name === 'readonly') for (const arg of args) shell.sealed.add(assigned(arg)?.[1] ?? bareOf(arg) ?? '')

    return
  }
  if ((DECLARES.has(name) && !isNamed) || (name === 'set' && !args.every(arg => SET.test(literalOf(arg) ?? '')))) return lose(shell)
  if (isTame(name, args, shell)) return
  strike(args, shell)
  forget(shell)
  // A name that is filled in may be the one the shell parts words by.
  if (!isWritten) shell.isWhole = false
}

/**
 * The launches a list of statements makes, in the order written, with what
 * is sure of the shell kept as each statement is passed. `home` is the home
 * directory the command began with.
 */
const scan = (statements: readonly Statement[], shell: Shell, home: string | undefined): FleetRun[] => {
  const runs: FleetRun[] = []
  let blocks = 0
  let parens = 0
  /** A function's body: due after its name, or open since the blocks and parentheses around it were this many. */
  let body: 'due' | number | undefined
  /** Whether a `[[` is open: what stands up to its `]]` is a test's words, and no command. */
  let isTesting = false

  for (const [index, { words, before, after, isOdd }] of statements.entries()) {
    const defined = definedAt(statements, index)
    let at = defined ?? 0
    let isTimed = false
    let isHeader = false

    // A function may stand for any command, and the shell calls some by itself, as zsh calls `chpwd` after a `cd`: past a definition, as past what is odd, nothing is sure.
    if (isOdd || defined !== undefined || (words.length === 0 && before === '(' && after === ')')) lose(shell)
    if (defined !== undefined) body = 'due'
    // The body opens with the word after the name, or with what follows the name's own parentheses.
    if (body === 'due' && (at < words.length || (defined === undefined && !(words.length === 0 && before === '(' && after === ')')))) body = blocks + parens
    for (let key = bareOf(words[at]) ?? ''; KEYWORDS.has(key) && !isTesting; key = bareOf(words[at]) ?? '') {
      // A loop runs its body again with what the body assigned: nothing known before it is sure inside.
      if (LOOPS.has(key)) forget(shell)
      // A `case` has patterns that close parentheses they did not open: where it ends is not followed.
      if (key === 'case') lose(shell)
      isTimed ||= key === 'time'
      // A loop's first line names its variable and what it goes through: there is no command in it.
      isHeader ||= key === 'for' || key === 'select'
      blocks = Math.max(0, blocks + (KEYWORDS.get(key) ?? 0))
      at += 1
    }
    // An assignment holds from here on only where the shell is sure to make it, in the shell the next statements run in.
    const isRun = blocks + parens === 0 && !CONDITIONAL.has(before) && !UNWAITED.has(after) && !isTimed && !isApart(statements, index)
    const first = at

    while (assigned(words[at]) !== null) at += 1
    const prefixed = words.slice(first, at)

    if (isTesting || nameOf(words[at]) === '[[') {
      // A test may assign, as arithmetic does.
      isTesting = !words.some(word => bareOf(word) === ']]')
      forget(shell)
    } else if (typeof body !== 'number') {
      // Whether a function is called is not told here: nothing in its body is taken to be run or assigned.
      // A command run to make a word runs in a shell of its own, which begins with what this one holds, less what this statement assigns.
      for (const piece of words.flatMap(word => word.pieces.filter(one => one.quote === '('))) {
        const inner = { ...shell, vars: new Map(shell.vars), sealed: new Set(shell.sealed) }

        strike(words.filter(word => assigned(word) !== null), inner)
        for (const run of scan(statementsOf(piece.text) ?? [], inner, home)) runs.push(run.specSpan === undefined ? run : { ...run, specSpan: [run.specSpan[0] + piece.from, run.specSpan[1] + piece.from] })
      }
      if (at === words.length && isRun) assign(prefixed, shell, shell.vars, false)
      else if (at === words.length) {
        // One made under a condition, in a block or in a shell of its own may not have been made.
        strike(prefixed, shell)
        if (prefixed.length > 0) forget(shell)
      } else if (!isHeader) {
        const wrappers: string[] = []
        let name = nameOf(words[at])

        // What is assigned before a command is that command's alone: its own arguments are filled in without it.
        while (name === 'timeout' || (name !== undefined && WRAPPERS.has(name))) {
          wrappers.push(name)
          at += name === 'timeout' ? 2 : 1
          while (assigned(words[at]) !== null) at += 1
          name = nameOf(words[at])
        }
        const args = words.slice(at + 1)
        /** What this command alone is given, before it or after `env`. */
        const lent = words.slice(first, at).map(word => assigned(word)?.[1] ?? '')
        const isDetached = wrappers.includes('nohup')

        // A variable a shell is ruled by, given to a command, rules the shell that command starts.
        if (lent.some(one => RULING.has(one))) lose(shell)
        const run = name === 'fleet-run' ? runOf(args, shell, after === '&', isDetached) : undefined
        const handed = run === undefined ? handedOf(name, args) : undefined
        const script = handed === undefined ? undefined : scriptOf(handed.word, shell)

        if (run !== undefined) runs.push(run)
        // The shell a script is handed to has this one's home directory only while this one has the one it began with, and is given no other.
        if (handed !== undefined && script !== undefined) {
          const inner = runsIn(script.text, shell.vars.get('HOME') === home && !lent.includes('HOME') ? home : undefined, shell.isLost || !handed.isPlain)

          runs.push(...inner.map(one => placed(one, script, after === '&', isDetached || name === 'orca')))
        }
        // `exec` may hand the shell's own variables on, and where it stands in a shell of its own zsh goes on from it in that one too, running
        // what follows twice; `env`, `nohup` and `timeout` run a program, which changes none; `command -v` only asks. Behind any of them a
        // builtin that assigns is not sure to assign: `command` runs it in bash and sh, and zsh looks for a program of its name.
        if (wrappers.includes('exec') && !isRun) lose(shell)
        else if (wrappers.includes('exec')) forget(shell)
        else if (wrappers.length > 0 && ASSIGNERS.has(bareOf(words[at]) ?? '')) affect(words[at], args, shell, false)
        else if (wrappers.every(one => one === 'command') && !(wrappers.length > 0 && /^-[vV]$/.test(bareOf(words[at]) ?? ''))) affect(words[at], args, shell, isRun)
        // Yet what is assigned before a command may outlast it, as before `export` or a special builtin of `sh`: what the variable held before is not sure after.
        strike(prefixed, shell)
      }
    }
    if (after === '(') parens += 1
    else if (after === ')') parens = Math.max(0, parens - 1)
    if (typeof body === 'number' && blocks + parens <= body) body = undefined
  }

  return runs
}

/** The launches a script makes, read by a shell that begins with this home directory; `isLost` where how that shell reads is not sure. */
const runsIn = (script: string, home: string | undefined, isLost: boolean): FleetRun[] => {
  const shell: Shell = {
    vars: new Map(home === undefined ? [] : [['HOME', home]]),
    sealed: new Set(),
    // `IFS` named anywhere may be `IFS` assigned: what a variable written bare holds may then be parted at any character.
    isWhole: !/\bIFS\b/.test(script),
    isLost,
  }

  return scan(statementsOf(script) ?? [], shell, home)
}

/**
 * The launches a command makes, in the order written: each `fleet-run` that
 * stands as a command of its own, behind `nohup` and its like or not, and
 * each in a script handed to a shell or to an Orca terminal in quotes. One
 * that is only text (a comment, a here-document's line, an argument another
 * command prints) is none, and neither is one in a function's body, which
 * runs only where the function is called.
 */
export const findFleetRuns = (command: string, home?: string): FleetRun[] => runsIn(command, home, false)

/** Where a character's copy of a spec goes: beside it, one name on, the character's own so that two do not share one. */
export const voicedSpecPath = (spec: string, who: string): string =>
  spec.endsWith('.md') ? `${spec.slice(0, -3)}.chiikawa-${who}.md` : `${spec}.chiikawa-${who}.md`

export type Meta = { isOk: boolean; note: string; tokens?: Tokens }

const count = (usage: Record<string, unknown>, key: string): number => {
  const value = usage[key]

  return typeof value === 'number' && Number.isFinite(value) ? value : 0
}

/**
 * A worker's usage as one shape. Each engine spells its own: Codex counts
 * the cached tokens inside `input_tokens`, the others beside them.
 */
export const readTokens = (usage: unknown): Tokens | undefined => {
  if (typeof usage !== 'object' || usage === null) return undefined
  const row = usage as Record<string, unknown>
  const inside = count(row, 'cached_input_tokens')
  const cached = inside + count(row, 'cache_read_input_tokens') + count(row, 'cache_read_tokens')
  const fresh = count(row, 'input_tokens') - inside + count(row, 'cache_creation_input_tokens')
  const out = count(row, 'output_tokens')
  const usd = typeof row.cost_usd === 'number' ? row.cost_usd : undefined

  return fresh + cached + out === 0 && usd === undefined ? undefined : { fresh: Math.max(0, fresh), cached, out, usd }
}

/** What a worker's `<out>.meta.json` says about how it ended. */
export const readMeta = (text: string, words: Pick<Words, 'took' | 'exitCode'>): Meta | undefined => {
  try {
    const meta: unknown = JSON.parse(text)

    if (typeof meta !== 'object' || meta === null) return undefined
    const { exit_code: code, model, seconds, status, usage } = meta as Record<string, unknown>
    const isOk = code === 0
    const took = typeof seconds === 'number' ? words.took(Math.round(seconds)) : ''
    const how = isOk ? '' : typeof status === 'string' ? status : words.exitCode(String(code))
    const note = [typeof model === 'string' ? model : '', took, how].filter(part => part !== '').join(' · ')

    return { isOk, note, tokens: readTokens(usage) }
  } catch {
    return undefined
  }
}

files.hooks/view.tsx:
import type { Color, Elements, RenderElement } from 'claude-code'

import type { Aid, Aids, Lang, MemberId, Mood, Roles, Said, Task, Tokens, Usage, WorkRole } from '../types'

import { ART_COLUMNS, ART_ROWS, artRows, ICON_COLUMNS, ICON_ROWS, iconOf } from './art'
import { bare, CAST, CORE, isActive, isGesture, jobOf, LEAD, MEMBERS, ORDER, PINK, roleOf, say, shortName, shown, titleOf, toneOf, WORK_ROLES, WORKERS } from './cast'
import type { Words } from './words'
import { inAll, WORDS } from './words'

/** How the drawings look just now: the tones of the person's theme, and the frame of what moves. */
export type Look = { isLight: boolean; frame: number }

export type Kit = Pick<Elements['terminal'], 'Box' | 'Text' | 'Raster' | 'Button'> & Look

export type Scene = {
  /** The language the screen is written in. */
  lang: Lang
  tasks: readonly Task[]
  now: number
  waveAt: number
  usage: Usage | null
  leaderTokens: Tokens
  feed: readonly Said[]
  /** The character the person's next prompt goes to, where they chose one. */
  picked: MemberId | null
  /** The character the pane tells of in full, where they asked about one. */
  watched: MemberId | null
  /** The hands lent to the main loop's own work, by whom and when. */
  aids: Aids
  /** Whether the pane shows the usage in full; one line of it otherwise. */
  isUsageOpen: boolean
  /** How many lines back from the last the pane's conversation is turned. */
  talkBack: number
  /** Whether the pane shows the conversation alone, as much of it as the pane holds. */
  isTalkOnly: boolean
  /** The roles the person gave; a character not named has its own. */
  roles: Roles
  /** What each character's tasks have cost so far, whatever has become of the tasks. */
  paid: Partial<Record<MemberId, Tokens>>
}

/** The room a pane has: the cells across its body, and the rows it may take. */
export type Room = { columns: number; rows: number }

/** Shows one character's task in full, or with `null` puts it away. */
export type OnWatch = (id: MemberId | null) => void

const MARK: Record<Task['status'], string> = { running: '●', waiting: '◐', done: '✓', failed: '✗' }
const TINT: Record<Task['status'], Color | undefined> = {
  running: undefined,
  waiting: 'warning',
  done: 'success',
  failed: 'error',
}

/** The mark of one at work, a frame at a time. */
const SPIN = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

const spin = (kit: Kit): string => SPIN[kit.frame % SPIN.length] ?? MARK.running

const lineOf = (kit: Kit, id: MemberId): Color => toneOf(MEMBERS[id].line, kit.isLight)

/** A name under the pointer: lit in the character's own colors. */
const lit = (id: MemberId): { backgroundColor: Color; color: Color; bold: true } => ({ backgroundColor: MEMBERS[id].color, color: MEMBERS[id].ink, bold: true })

/** How long a hand lent to the main loop's work shows as one. */
export const AID_MS = 12_000

/** The hand a character is lending just now, if it is. */
export const aidOf = (scene: Pick<Scene, 'aids' | 'now'>, id: MemberId): Aid | undefined => {
  const aid = scene.aids[id]

  return aid !== undefined && scene.now - aid.at < AID_MS ? aid : undefined
}

const WIDE: readonly (readonly [number, number])[] = [
  [0x1100, 0x115f],
  [0x2e80, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe30, 0xfe4f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x1f1e6, 0x1f1ff],
  [0x1f300, 0x1faff],
  [0x20000, 0x3fffd],
]

const JOINED = /^(?:\p{M}|[\u200d\ufe0e\ufe0f\u{1f3fb}-\u{1f3ff}])$/u
const FLAG = /^[\u{1f1e6}-\u{1f1ff}]$/u
/** A sign a terminal draws as a picture with no selector asking for it: `✅`, `⌚`, `⏰`. */
const PICTURED = /^\p{Emoji_Presentation}/u

/** The text as the units a terminal draws: a letter with its accents, an emoji with all that is joined to it. */
const clusters = (text: string): string[] => {
  const units: string[] = []
  let isJoining = false

  for (const char of text) {
    const last = units[units.length - 1]
    const isPair = last !== undefined && FLAG.test(last) && FLAG.test(char)

    if (last !== undefined && (isJoining || isPair || JOINED.test(char))) units[units.length - 1] = last + char
    else units.push(char)
    isJoining = char === '\u200d'
  }

  return units
}

const cellsOfCluster = (unit: string): number => {
  const code = unit.codePointAt(0) ?? 0

  // A mark with nothing to sit on takes no cell.
  if (JOINED.test(String.fromCodePoint(code))) return 0

  // A sign in its picture form is two cells, whatever its own width: one the selector asks it of, or one drawn so unasked.
  return unit.includes('\ufe0f') || PICTURED.test(unit) || WIDE.some(([from, to]) => code >= from && code <= to) ? 2 : 1
}

/** Cells a string takes on a terminal row: Hangul, kana and emoji take two. */
export const cells = (text: string): number => clusters(text).reduce((total, unit) => total + cellsOfCluster(unit), 0)

/** The start of the text that goes in a width in cells, with nothing standing for the rest. */
const clip = (text: string, width: number): string => {
  let kept = ''
  let used = 0

  for (const unit of clusters(text)) {
    const next = cellsOfCluster(unit)

    if (used + next > width) break
    kept += unit
    used += next
  }

  return kept
}

/** The text cut to a width in cells, an ellipsis standing for what was cut. */
export const fit = (text: string, width: number): string => {
  if (width <= 0) return ''

  return cells(text) <= width ? text : `${clip(text, width - 1)}…`
}

/** The text cut to a width from its start, an ellipsis standing for what was cut: a path keeps its file's name. */
export const fitEnd = (text: string, width: number): string => {
  if (width <= 0) return ''
  if (cells(text) <= width) return text
  const units = clusters(text)
  let kept = ''
  let used = 0

  for (let at = units.length - 1; at >= 0; at -= 1) {
    const unit = units[at] ?? ''
    const next = cellsOfCluster(unit)

    if (used + next > width - 1) break
    kept = unit + kept
    used += next
  }

  return `…${kept}`
}

export const pad = (text: string, width: number): string => text + ' '.repeat(Math.max(0, width - cells(text)))

const wordsOf = (scene: Pick<Scene, 'lang'>): Words => WORDS[scene.lang]

const nameOf = (scene: Pick<Scene, 'lang'>, id: MemberId): string => CAST[scene.lang].names[id]

/** A character's name in a width: its short one where the whole does not go in, cut where even that does not. */
const nameIn = (lang: Lang, id: MemberId, width: number, most = width): string => {
  const whole = CAST[lang].names[id]

  return cells(whole) <= width ? whole : fit(shortName(lang, id), most)
}

export const clock = (ms: number): string => {
  const seconds = Math.max(0, Math.floor(ms / 1000))

  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
}

export const elapsed = (task: Task, now: number): number => (task.endedAt ?? Math.max(now, task.startedAt)) - task.startedAt

/** The tasks of the wave in hand: the active ones first, then the newest. */
export const onStage = (scene: Scene): Task[] =>
  scene.tasks
    .filter(task => task.startedAt >= scene.waveAt || isActive(task))
    .sort((a, b) => Number(isActive(b)) - Number(isActive(a)) || b.startedAt - a.startedAt)

/** The last line said, by anyone or by one character. */
export const lastSaid = (scene: Pick<Scene, 'feed'>, id?: MemberId): Said | undefined => {
  for (let at = scene.feed.length - 1; at >= 0; at -= 1) {
    const said = scene.feed[at]

    if (said !== undefined && (id === undefined || said.member === id)) return said
  }

  return undefined
}

const isRunning = (task: Task): boolean => task.status === 'running'

/** The ones at work. One whose task waits, on an answer or on a result that has not come, is not: it rests until it goes on. */
const busyOf = (scene: Scene): MemberId[] => WORKERS.filter(id => scene.tasks.some(task => task.member === id && isRunning(task)))

const waitingOf = (scene: Scene): MemberId[] => WORKERS.filter(id => !scene.tasks.some(task => task.member === id && isRunning(task)) && scene.tasks.some(task => task.member === id && isActive(task)))

/** Whether a character is at work: one with a task in hand or lending a hand, and 하치와레 while anyone has a task. */
const isAtWork = (scene: Scene, id: MemberId): boolean => aidOf(scene, id) !== undefined || scene.tasks.some(task => isRunning(task) && (id === LEAD || task.member === id))

const Badge = ({ Text }: Kit, id: MemberId, name: string): RenderElement => (
  <Text backgroundColor={MEMBERS[id].color} color={MEMBERS[id].ink} bold>
    {` ${name} `}
  </Text>
)

const Dot = (kit: Kit, id: MemberId): RenderElement => <kit.Text color={lineOf(kit, id)}>● </kit.Text>

/** A character's picture in keyboard characters, wearing the mood's face; one at work walks. */
const Picture = (kit: Kit, id: MemberId, mood: Mood, isWalking = false): RenderElement => {
  const { Box, Text } = kit

  return (
    <Box flexDirection="column" width={ART_COLUMNS}>
      {artRows(id, mood, kit.isLight, isWalking && kit.frame % 2 === 1).map((runs, row) => (
        <Text key={`art-${row}`}>
          {runs.map((run, index) => (
            <Text key={`run-${index}`} color={run.color}>
              {run.text}
            </Text>
          ))}
        </Text>
      ))}
    </Box>
  )
}

/** A character's pixel icon; one at work bounces. */
const Icon = (kit: Kit, id: MemberId, isBouncing = false): RenderElement => (
  <kit.Raster key={`icon-${id}`} columns={ICON_COLUMNS} rows={ICON_ROWS} cells={iconOf(id, kit.isLight, isBouncing && kit.frame % 2 === 1)} />
)

/** A line or a gesture in the character's color; a gesture is told plainly, a line in italics. */
const Quote = (kit: Kit, id: MemberId, quote: string, width: number): RenderElement => (
  <kit.Text color={lineOf(kit, id)} italic={!isGesture(quote)}>
    {fit(shown(quote), width)}
  </kit.Text>
)

// ---- usage

export const ZERO: Tokens = { fresh: 0, cached: 0, out: 0 }

export const plus = (a: Tokens, b: Tokens | undefined): Tokens => {
  if (b === undefined) return a
  const usd = a.usd === undefined && b.usd === undefined ? undefined : (a.usd ?? 0) + (b.usd ?? 0)

  return { fresh: a.fresh + b.fresh, cached: a.cached + b.cached, out: a.out + b.out, usd }
}

export const spent = (lang: Lang, tokens: Tokens): string => {
  const { amount, tokens: told } = WORDS[lang]
  const cost = tokens.usd === undefined ? '' : ` · $${tokens.usd.toFixed(2)}`

  return `${told(amount(tokens.fresh), amount(tokens.cached), amount(tokens.out))}${cost}`
}

/** What each character has spent so far: what its tasks have cost, 하치와레's the main loop's. */
export const spentBy = (scene: Pick<Scene, 'paid' | 'leaderTokens'>): Record<MemberId, Tokens> => {
  const by = Object.fromEntries(ORDER.map(id => [id, scene.paid[id] ?? ZERO])) as Record<MemberId, Tokens>

  by[LEAD] = scene.leaderTokens

  return by
}

const isSpent = (tokens: Tokens): boolean => tokens.fresh + tokens.cached + tokens.out > 0 || tokens.usd !== undefined

/** When a window resets, as the language says it. */
export const until = (lang: Lang, at: number, now: number): string => WORDS[lang].until(Math.max(0, Math.round((at - now) / 60_000)))

const bar = (percent: number): string => {
  const lit = percent <= 0 ? 0 : Math.max(1, Math.min(10, Math.round(percent / 10)))

  return '▰'.repeat(lit) + '▱'.repeat(10 - lit)
}

/** The context window still free, 0 to 100, when the engine has a reading. */
export const batteryOf = (usage: Usage | null): number | undefined =>
  usage?.contextPercent === undefined ? undefined : Math.max(0, 100 - usage.contextPercent)

/** The band's one-glance gauge, the part to keep longest first: battery left, and the five-hour window. */
export const gaugeParts = (lang: Lang, usage: Usage | null): string[] => {
  const words = WORDS[lang]
  const free = batteryOf(usage)
  const window = usage?.limits.find(limit => limit.kind === 'five_hour')

  return [free === undefined ? '' : `${words.battery} ${Math.round(free)}%`, window === undefined ? '' : `${words.limits.five_hour ?? ''} ${window.percentUsed}%`].filter(part => part !== '')
}

type Meter = { label: string; percent: number; tint: Color; text: string }

/** The cells a meter's label takes with the cell after it: the widest the language has. */
const labelCells = (words: Words): number => Math.max(cells(words.battery), ...Object.values(words.limits).map(cells)) + 1

const metersOf = (scene: Scene): Meter[] => {
  const { usage } = scene
  const words = wordsOf(scene)
  const free = batteryOf(usage)
  const meters: Meter[] = []

  if (usage !== null && free !== undefined) {
    meters.push({
      label: words.battery,
      percent: free,
      tint: free < 20 ? 'error' : free < 40 ? 'warning' : 'success',
      text: words.left(Math.round(free), words.amount(usage.contextTokens ?? 0), words.amount(usage.contextWindow)),
    })
  }
  for (const limit of usage?.limits ?? []) {
    const reset = limit.resetsAt === undefined ? '' : ` · ${until(scene.lang, limit.resetsAt, scene.now)}`

    meters.push({
      label: words.limits[limit.kind] ?? limit.kind,
      percent: limit.percentUsed,
      tint: limit.percentUsed >= 90 ? 'error' : limit.percentUsed >= 70 ? 'warning' : 'success',
      text: `${words.used(limit.percentUsed)}${reset}`,
    })
  }

  return meters
}

const spendersOf = (scene: Scene): MemberId[] => {
  const by = spentBy(scene)

  return ORDER.filter(id => isSpent(by[id]))
}

/** The cells a spender's name has in the usage card, with the cell after it. */
const PAID_NAME = 15

/** Rows the usage card takes, frame and all. */
const usageRows = (scene: Scene): number => {
  const spenders = spendersOf(scene).length
  const rows = metersOf(scene).length + (spenders === 0 ? 0 : spenders + 1)

  return 2 + 1 + Math.max(1, rows)
}

/** The usage card: the session's battery, the plan's windows, who earned what. */
const UsageCard = (kit: Kit, scene: Scene, width: number, onUsage: () => void): RenderElement => {
  const { Box, Text, Button } = kit
  const inner = width - 4
  const words = wordsOf(scene)
  const meters = metersOf(scene)
  const by = spentBy(scene)
  const spenders = spendersOf(scene)
  const usd = scene.usage?.usd
  const label = labelCells(words)

  return (
    <Box borderStyle="round" borderColor="subtle" paddingX={1} flexDirection="column" width={width}>
      <Box justifyContent="space-between" width={inner}>
        <Box gap={1}>
          <Text bold>{words.usage}</Text>
          {usd !== undefined && <Text dimColor>{fit(words.session(usd.toFixed(2)), inner - cells(words.usage) - cells(words.fold) - 3)}</Text>}
        </Box>
        <Button key="usage-less" label={words.fold} plain dimColor onPress={() => onUsage()} />
      </Box>
      {meters.map(meter => (
        <Text key={meter.label} wrap="truncate-end">
          <Text dimColor>{pad(meter.label, label)}</Text>
          <Text color={meter.tint}>{bar(meter.percent)}</Text>
          <Text>{` ${fit(meter.text, inner - label - 11)}`}</Text>
        </Text>
      ))}
      {spenders.length > 0 && <Text dimColor>{fit(words.pay, inner)}</Text>}
      {spenders.map(id => (
        <Text key={id} wrap="truncate-end">
          {Dot(kit, id)}
          <Text>{pad(nameIn(scene.lang, id, PAID_NAME - 1), PAID_NAME)}</Text>
          <Text dimColor>{fit(spent(scene.lang, by[id]), inner - PAID_NAME - 2)}</Text>
        </Text>
      ))}
      {meters.length === 0 && spenders.length === 0 && <Text dimColor>{fit(words.noUsage, inner)}</Text>}
    </Box>
  )
}

// ---- the conversation, a line to a row: where there is no room for a comic

/** One line of the conversation: who, what was said or done, and what it was about. */
const TalkRow = (kit: Kit, lang: Lang, said: Said, width: number, key: string): RenderElement => {
  const { Text } = kit
  const name = CAST[lang].names[said.member]
  const room = width - cells(name) - 3
  const quote = said.quote[lang]
  const note = said.note[lang]
  const noteRoom = room - cells(fit(shown(quote), room)) - 1

  return (
    <Text key={key} wrap="truncate-end">
      {Badge(kit, said.member, name)}
      <Text> </Text>
      {Quote(kit, said.member, quote, room)}
      {note !== '' && noteRoom >= 6 && <Text dimColor>{` ${fit(note, noteRoom)}`}</Text>}
    </Text>
  )
}

/** What stands for the conversation before anything was said: 하치와레, waiting for work. */
const waitingSaid: Said = { member: LEAD, quote: inAll(lang => CAST[lang].leader.idle), note: inAll(lang => WORDS[lang].awaiting), at: 0, mood: 'calm' }

/** The last lines of the conversation, oldest first, beside the picture of whoever spoke last. */
const Talk = (kit: Kit, scene: Scene, width: number, lines: number, withPicture: boolean): RenderElement => {
  const { Box } = kit
  const said = scene.feed.length === 0 ? [waitingSaid] : scene.feed.slice(-Math.max(1, lines))
  const latest = said[said.length - 1] ?? waitingSaid
  const room = withPicture ? width - ART_COLUMNS - 1 : width

  return (
    <Box gap={1} width={width}>
      {withPicture && Picture(kit, latest.member, latest.mood, isAtWork(scene, latest.member))}
      <Box flexDirection="column" width={room} justifyContent="flex-end">
        {said.map((one, index) => TalkRow(kit, scene.lang, one, room, `said-${one.at}-${index}`))}
      </Box>
    </Box>
  )
}

// ---- the conversation as a comic: a picture, and a balloon for what was said

/** The narrowest a cut is drawn: a picture, and a balloon that holds a short line. */
const CUT_COLUMNS = 46
const MAX_CUTS = 8
/** The cuts the conversation has before the ones resting are given seats. */
const MIN_CUTS = 3

const isShout = (quote: string): boolean => /[!！]\s*$/.test(quote)

/**
 * One cut of the comic: the speaker's picture, and a balloon with its name on
 * the rim and its tail toward the picture. A gesture is a caption instead, a
 * square box with no tail. What the line is about stands dim beside the
 * balloon, or on its lower rim where there is no room beside. `isTurned` puts
 * the picture on the right, so that two cuts face each other.
 */
const Cut = (kit: Kit, lang: Lang, said: Said, width: number, isTurned: boolean, isWalking: boolean, key: string): RenderElement => {
  const { Box, Text } = kit
  const line = lineOf(kit, said.member)
  const quote = said.quote[lang]
  const note = said.note[lang]
  const isCaption = isGesture(quote)
  const words = bare(quote)
  const room = width - ART_COLUMNS - 1
  const name = nameIn(lang, said.member, Math.max(2, room - 6))
  const own = Math.max(cells(words), cells(name) + 2) + 4
  const isBeside = note !== '' && room - own - 1 >= Math.min(cells(note), 10)
  const outer = Math.max(cells(name) + 6, Math.min(room, isBeside || note === '' ? own : Math.max(own, cells(note) + 6)))
  const [topLeft, topRight, bottomLeft, bottomRight] = isCaption ? ['┌', '┐', '└', '┘'] : ['╭', '╮', '╰', '╯']
  const text = fit(words, outer - 4)
  const fill = ' '.repeat(Math.max(0, outer - 4 - cells(text)))
  const beside = isBeside ? fit(note, room - outer - 1) : ''
  const under = isBeside || note === '' ? '' : fit(note, outer - 6)
  const rim = '─'.repeat(Math.max(0, outer - 5 - cells(name)))
  const foot = '─'.repeat(Math.max(0, under === '' ? outer - 2 : outer - 5 - cells(under)))
  const push = ' '.repeat(Math.max(0, room - outer))
  const lead = beside === '' ? push : `${' '.repeat(Math.max(0, room - outer - 1 - cells(beside)))}${beside} `
  const tail = isCaption ? '│' : isTurned ? '>' : '<'
  const picture = Picture(kit, said.member, said.mood, isWalking)

  return (
    <Box key={key} gap={1} width={width}>
      {!isTurned && picture}
      <Box flexDirection="column" width={room}>
        <Text wrap="truncate-end">
          <Text color={line}>{isTurned ? `${push}${topLeft}${rim}` : `${topLeft}─`}</Text>
          {Badge(kit, said.member, name)}
          <Text color={line}>{isTurned ? `─${topRight}` : `${rim}${topRight}`}</Text>
        </Text>
        <Text wrap="truncate-end">
          {isTurned && <Text dimColor>{lead}</Text>}
          <Text color={line}>{isTurned ? '│ ' : `${tail} `}</Text>
          <Text color={line} italic={!isCaption} bold={isShout(words)}>
            {text}
          </Text>
          <Text color={line}>{`${fill} ${isTurned ? tail : '│'}`}</Text>
          {!isTurned && beside !== '' && <Text dimColor>{` ${beside}`}</Text>}
        </Text>
        <Text wrap="truncate-end">
          <Text color={line}>{`${isTurned ? push : ''}${bottomLeft}${under === '' ? '' : '─ '}`}</Text>
          {under !== '' && <Text dimColor>{under}</Text>}
          <Text color={line}>{`${under === '' ? '' : ' '}${foot}${bottomRight}`}</Text>
        </Text>
      </Box>
      {isTurned && picture}
    </Box>
  )
}

/** Which lines of the conversation a page of `count` cuts holds, turned back as far as the person turned it. */
const shownOf = (scene: Scene, count: number): { from: number; to: number } => {
  const size = Math.max(1, count)
  const to = Math.max(Math.min(size, scene.feed.length), scene.feed.length - Math.max(0, scene.talkBack))

  return { from: Math.max(0, to - size), to }
}

/** The last lines of the conversation as cuts down a page, oldest first: the friends on the left, 하치와레 answering from the right. */
const Page = (kit: Kit, scene: Scene, width: number, count: number): RenderElement => {
  const { from, to } = shownOf(scene, count)
  const said = scene.feed.length === 0 ? [waitingSaid] : scene.feed.slice(from, to)

  return (
    <kit.Box flexDirection="column" width={width}>
      {said.map((one, index) => Cut(kit, scene.lang, one, width, one.member === LEAD, isAtWork(scene, one.member), `cut-${one.at}-${index}`))}
    </kit.Box>
  )
}

// ---- the band

/** What the band shows and what a press in it asks for. */
export type Band = {
  /** Whether there is a conversation to show under the row of friends. */
  isLive: boolean
  /** A friend was pressed: the pane shows what it is doing. */
  onSeat: (id: MemberId) => void
  /** The count of friends the row has no room to name was pressed: the pane opens. */
  onOpen: () => void
  /** The usage was pressed: the pane opens with the usage in full. */
  onUsage: () => void
  /** Who takes the next prompt was pressed: a chosen friend is let go, and 하치와레 decides again. */
  onAuto: () => void
}

type Seat = {
  id: MemberId
  /** The mark of its task in this wave; none for one with no task. */
  glyph: string
  isRunning: boolean
  tint: Color | undefined
  label: string
  /** How long its task has run, while it runs. */
  time: string
  isBusy: boolean
  isDim: boolean
}

const SEAT_GAP = 2
const GUESTS: readonly MemberId[] = WORKERS.filter(id => !CORE.includes(id))

const seatOf = (scene: Scene, stage: readonly Task[], id: MemberId): Seat => {
  const task = id === LEAD ? stage.find(isRunning) : stage.find(one => one.member === id)
  const isHelping = aidOf(scene, id) !== undefined && (task === undefined || !isActive(task))
  // One that waits keeps its mark and its time, and is counted with the ones resting.
  const isBusy = isHelping || (task !== undefined && isRunning(task))
  const isPicked = scene.picked === id

  return {
    id,
    glyph: isHelping ? MARK.running : task === undefined ? '' : id === LEAD ? MARK.running : MARK[task.status],
    isRunning: isHelping || (task !== undefined && (id === LEAD || task.status === 'running')),
    tint: isHelping || task === undefined || id === LEAD ? undefined : TINT[task.status],
    label: `${isPicked ? '▶' : ''}${shortName(scene.lang, id)}`,
    time: id !== LEAD && task !== undefined && isActive(task) ? ` ${clock(elapsed(task, scene.now))}` : '',
    isBusy,
    isDim: !isPicked && !isBusy,
  }
}

const seatCells = (seat: Seat, hasTime: boolean): number => SEAT_GAP + (seat.glyph === '' ? 0 : 2) + cells(seat.label) + (hasTime ? cells(seat.time) : 0)

type BandRow = {
  /** The three the comic is about: always named. */
  core: Seat[]
  /** The others the row names. */
  guests: Seat[]
  /** What stands for the others it has no room to name; empty where it names them all. */
  rest: string
  hasTime: boolean
  /** Who takes the next prompt; empty where there is no room to say. */
  to: string
  gauge: string
}

/**
 * The fullest row the band's width holds, least room last: everyone by name,
 * then the three and whoever is at work with the rest as a count, then the
 * three alone; the time a task has run goes before a name does, then the
 * gauge's second half, then who takes the next prompt.
 */
const rowOf = (scene: Scene, columns: number): BandRow => {
  const stage = onStage(scene)
  const core = CORE.map(id => seatOf(scene, stage, id))
  const guests = GUESTS.map(id => seatOf(scene, stage, id))
  const called = guests.filter(seat => seat.isBusy || scene.picked === seat.id)
  const words = wordsOf(scene)
  // The mode's name in its badge, a cell either side.
  const title = cells(words.brand) + 2
  const parts = gaugeParts(scene.lang, scene.usage)
  const whole = parts.length === 0 ? words.usage : parts.join(' · ')
  const brief = parts[0] ?? whole
  const sent = words.sent(scene.picked === null ? words.auto : shortName(scene.lang, scene.picked))
  const tries: readonly (readonly [named: Seat[], hasTime: boolean, gauge: string, to: string])[] = [
    [guests, true, whole, sent],
    [guests, false, whole, sent],
    [guests, false, brief, sent],
    [called, true, whole, sent],
    [called, false, whole, sent],
    [called, false, brief, sent],
    [[], false, brief, sent],
    [[], false, brief, ''],
    [[], false, '', ''],
  ]

  for (const [named, hasTime, gauge, to] of tries) {
    const unnamed = guests.filter(seat => !named.includes(seat))
    const atWork = unnamed.filter(seat => seat.isBusy).length
    const resting = unnamed.length - atWork
    const counts = [atWork === 0 ? '' : words.working(atWork), resting === 0 ? '' : words.resting(resting)].filter(part => part !== '')
    const seats = [...core, ...named].reduce((total, seat) => total + seatCells(seat, hasTime), 0)

    // Both counts where they fit, and the one of those at work where they do not.
    for (const rest of counts.length === 2 ? [counts.join(' · '), counts[0] ?? ''] : [counts[0] ?? '']) {
      const used = title + seats + (named.length === 0 ? 0 : SEAT_GAP + 1) + (rest === '' ? 0 : SEAT_GAP + cells(rest)) + (to === '' ? 0 : SEAT_GAP + cells(to)) + (gauge === '' ? 0 : SEAT_GAP + cells(gauge))

      if (used <= columns) return { core, guests: named, rest, hasTime, to, gauge }
    }
  }

  return { core: [], guests: [], rest: '', hasTime: false, to: '', gauge: title + 1 + cells(brief) <= columns ? brief : '' }
}

/** One friend in the band's row: the mark of its task, its name to press, and how long the task has run. */
const SeatBox = (kit: Kit, seat: Seat, hasTime: boolean, onSeat: (id: MemberId) => void): RenderElement => {
  const { Box, Text, Button } = kit
  const tone = seat.tint ?? lineOf(kit, seat.id)

  return (
    <Box key={seat.id}>
      {seat.glyph !== '' && <Text color={tone}>{`${seat.isRunning ? spin(kit) : seat.glyph} `}</Text>}
      <Button key={`seat-${seat.id}`} label={seat.label} plain dimColor={seat.isDim} hover={lit(seat.id)} onPress={() => onSeat(seat.id)} />
      {hasTime && seat.time !== '' && <Text color={tone}>{seat.time}</Text>}
    </Box>
  )
}

/**
 * The band above the prompt: the friends by name, each to press, the three
 * the comic is about first and the others after a rule; at the right end
 * who takes the next prompt (하치와레 decides, unless a friend was chosen)
 * and the usage; and under them the last line said, as one cut, while there
 * is a conversation the pane is not showing.
 */
export const drawBand = (kit: Kit, scene: Scene, columns: number, rows: number, band: Band): RenderElement => {
  const { Box, Text, Button } = kit
  const row = rowOf(scene, columns)
  const isTalking = band.isLive && scene.feed.length > 0
  const latest = isTalking ? scene.feed[scene.feed.length - 1] : undefined
  const isComic = rows - 1 >= ART_ROWS && columns >= CUT_COLUMNS

  return (
    <Box flexDirection="column" width={columns}>
      <Box justifyContent="space-between" width={columns}>
        <Box gap={SEAT_GAP}>
          <Text backgroundColor={PINK} color="#000000" bold>
            {` ${wordsOf(scene).brand} `}
          </Text>
          {row.core.map(seat => SeatBox(kit, seat, row.hasTime, band.onSeat))}
          {row.guests.length > 0 && <Text dimColor>│</Text>}
          {row.guests.map(seat => SeatBox(kit, seat, row.hasTime, band.onSeat))}
          {row.rest !== '' && <Button key="rest" label={row.rest} plain dimColor onPress={() => band.onOpen()} />}
        </Box>
        <Box gap={SEAT_GAP}>
          {row.to !== '' && <Button key="to" label={row.to} plain dimColor={scene.picked === null} onPress={() => band.onAuto()} />}
          {row.gauge !== '' && <Button key="usage" label={row.gauge} plain dimColor onPress={() => band.onUsage()} />}
        </Box>
      </Box>
      {latest !== undefined && isComic && Cut(kit, scene.lang, latest, Math.min(columns, 84), false, isAtWork(scene, latest.member), 'cut')}
      {latest !== undefined && !isComic && rows >= 2 && TalkRow(kit, scene.lang, latest, columns, 'said')}
    </Box>
  )
}

// ---- the pane: the three the comic is about, a card for each guest at work, the rest on the bench

/** What a press in the pane asks for. */
export type PaneActs = {
  onWatch: OnWatch
  /** The character whose sheet is open is to take the person's next prompt, or no longer to. */
  onPick: (id: MemberId) => void
  /** The usage is to be shown in full, or put back to its one line. */
  onUsage: () => void
  /** The conversation is to be turned so many lines back from the last; 0 for the last ones. */
  onTalk: (back: number) => void
  /** The conversation is to be shown alone, or the whole page again. */
  onStory: () => void
  /** A character is given a role; its own role gives it back what it had. */
  onRole: (id: MemberId, role: WorkRole) => void
}

type Card = {
  id: MemberId
  name: string
  sub: string
  status: string
  tint: Color | undefined
  isIdle: boolean
  /** At work this moment: its mark turns and its picture moves. */
  isRunning: boolean
  /** Its task has ended. */
  isEnded: boolean
  work: string
  /** The task's name alone, where the card is about one. */
  title?: string
  quote: string
  note: string
  /** What it is on now, or what it handed back. */
  last: string
}

/** The day so far, for 하치와레's card: the tasks that ended well, and the ones that failed; nothing before any has ended. */
const tally = (scene: Scene): { done: number; failed: number } | undefined => {
  const ended = scene.tasks.filter(task => !isActive(task))
  const failed = ended.filter(task => task.status === 'failed').length

  return ended.length === 0 ? undefined : { done: ended.length - failed, failed }
}

/** A character's tasks, the newest first. */
const tasksOf = (scene: Scene, id: MemberId): Task[] => scene.tasks.filter(task => task.member === id).sort((a, b) => b.startedAt - a.startedAt)

/** The engine a task runs on: an Orca worker's profile is told as one; a demonstration, which is due at a set time, has only the language's word for one. */
const engineOf = (words: Words, task: Task): string => (task.due !== undefined ? words.demo : task.kind === 'orca' ? `Orca ${task.engine}` : task.engine)

const doingOf = (words: Words, task: Task): string => {
  const on = task.detail === undefined || task.detail === '' ? '' : ` ${task.detail}`

  return task.tool === undefined ? '' : `▸ ${task.tool}${on} · ${words.tools(task.toolCount)}`
}

const cardOf = (id: MemberId, scene: Scene): Card => {
  const words = wordsOf(scene)
  const { lang } = scene
  const cast = CAST[lang]
  const name = cast.names[id]
  const sub = [cast.kinds[id], cast.titles[id], cast.job[roleOf(id, scene.roles)]].filter(part => part !== '').join(' · ')
  const idle = `○ ${words.idle}`

  if (id === LEAD || id === 'rodo') {
    const busy = busyOf(scene)
    const said = lastSaid(scene, id)
    const doing = id === LEAD ? words.leading : words.receiving
    const day = tally(scene)
    // With no friend called in, 하치와레 is at the work himself, the other two lending a hand.
    const own = id === LEAD && busy.length === 0 ? aidOf(scene, LEAD) : undefined
    const hands = CORE.filter(one => one !== LEAD && aidOf(scene, one) !== undefined)
    const isAlone = busy.length === 0 && own === undefined
    const what = own?.what[lang]

    return {
      id,
      name,
      sub,
      status: isAlone ? idle : `${MARK.running} ${own === undefined ? doing : hands.length === 0 ? words.alone : words.together}`,
      tint: undefined,
      isIdle: isAlone,
      isRunning: !isAlone,
      isEnded: false,
      work: what ?? (busy.length === 0 ? words.awaiting : words.atWork(busy.map(one => cast.names[one]))),
      // In a cut: how many have the work, or whose hand he has; the sheet has the rest.
      ...(id !== LEAD ? {} : busy.length > 0 ? { title: words.handed(busy.length) } : what !== undefined ? { title: own?.brief?.[lang] ?? what.split(' · ')[0] ?? what } : {}),
      quote: said?.quote[lang] ?? say(lang, id, 'idle', 0),
      note: said?.note[lang] ?? '',
      last: id === LEAD && day !== undefined ? words.tally(day.done, day.failed) : '',
    }
  }

  const own = tasksOf(scene, id)
  const task = own.find(isActive) ?? own[0]
  const aid = aidOf(scene, id)

  if (aid !== undefined && (task === undefined || !isActive(task))) {
    const said = lastSaid(scene, id)

    return { id, name, sub, status: `${MARK.running} ${words.helping}`, tint: undefined, isIdle: false, isRunning: true, isEnded: false, work: aid.what[lang], quote: said?.quote[lang] ?? say(lang, id, 'start', 0), note: said?.note[lang] ?? '', last: '' }
  }
  if (task === undefined) {
    return { id, name, sub, status: idle, tint: undefined, isIdle: true, isRunning: false, isEnded: false, work: jobOf(lang, id, scene.roles), quote: say(lang, id, 'idle', 0), note: '', last: '' }
  }

  const active = own.filter(isActive).length
  const more = active > 1 ? ` ${words.more(active - 1)}` : ''
  const back = task.report === undefined ? '' : `↳ ${task.report[lang]}`
  const title = `${titleOf(lang, task)}${more}`

  return {
    id,
    name,
    sub,
    status: `${MARK[task.status]} ${words.status[task.status]} ${clock(elapsed(task, scene.now))}`,
    tint: TINT[task.status],
    isIdle: false,
    isRunning: task.status === 'running',
    isEnded: !isActive(task),
    work: `${title} · ${engineOf(words, task)}`,
    title,
    quote: task.quote[lang],
    note: task.note[lang],
    last: isActive(task) ? doingOf(words, task) : back,
  }
}

/** A card's state as drawn: the mark of one at work turns. */
const statusOf = (kit: Kit, card: Card): string => (card.isRunning ? card.status.replace(MARK.running, spin(kit)) : card.status)

/** A card's state in its color. */
const State = (kit: Kit, card: Card): RenderElement => (
  <kit.Text color={card.tint} bold={!card.isIdle} dimColor={card.isIdle}>
    {statusOf(kit, card)}
  </kit.Text>
)

/**
 * A character's name as the thing to press: the pane then shows what that
 * character is doing. It lights up in the character's colors while its card
 * is under the pointer.
 */
const Name = (kit: Kit, id: MemberId, onWatch: OnWatch, label: string, isDim = false): RenderElement => (
  <kit.Button key={`watch-${id}`} label={label} plain dimColor={isDim} hover={lit(id)} onPress={() => onWatch(id)} />
)

/** A card's first row: the name to press, short where the whole of it would push the state past the edge, and its state at the right edge. */
const Head = (kit: Kit, lang: Lang, card: Card, width: number, onWatch: OnWatch): RenderElement => (
  <kit.Box justifyContent="space-between" width={width}>
    <kit.Box>
      {Dot(kit, card.id)}
      {Name(kit, card.id, onWatch, nameIn(lang, card.id, width - 3 - cells(card.status)))}
    </kit.Box>
    {State(kit, card)}
  </kit.Box>
)

/** Two rows a character behind a bar of its color: for a pane a few rows tall. */
const SlimCard = (kit: Kit, lang: Lang, card: Card, width: number, onWatch: OnWatch): RenderElement => {
  const { Box, Text } = kit
  const line = lineOf(kit, card.id)
  const quote = fit(shown(card.quote), Math.min(24, Math.floor(width / 2)))

  return (
    <Box key={card.id} flexDirection="column" width={width}>
      <Box width={width}>
        <Text color={line}>▌</Text>
        {Head(kit, lang, card, width - 1, onWatch)}
      </Box>
      <Text wrap="truncate-end">
        <Text color={line}>▌</Text>
        <Text dimColor={card.isIdle}>{`  ${fit(card.work, width - 4 - cells(quote))} `}</Text>
        <Text color={line} italic={!isGesture(card.quote)}>
          {quote}
        </Text>
      </Text>
    </Box>
  )
}

/** A row with what it holds set in its middle by hand: a Button takes the start of the row it is given. */
const Middle = (kit: Kit, width: number, used: number, held: RenderElement): RenderElement => {
  const lead = Math.max(0, Math.floor((width - used) / 2))

  return (
    <kit.Box width={width}>
      {lead > 0 && <kit.Text>{' '.repeat(lead)}</kit.Text>}
      {held}
    </kit.Box>
  )
}

/** Rows a cut holds inside its frame: the icon, the name, its state, and what it is on. */
const PANEL_ROWS = ICON_ROWS + 3

/**
 * A character on the page, as a cut of its own: the icon over the name to
 * press, its state, and one line of what it is on, handed back or last said.
 * The frame takes the character's color while it is at work; who it is and
 * the rest of what it is doing are on its sheet.
 */
const Panel = (kit: Kit, lang: Lang, card: Card, width: number, onWatch: OnWatch): RenderElement => {
  const { Box, Text } = kit
  const inner = width - 4
  const line = lineOf(kit, card.id)
  const name = nameIn(lang, card.id, inner)
  // With nothing in hand and nothing handed back, the cut shows what the character last said.
  const isTold = card.isIdle || (card.isEnded && card.last === '')
  const about = isTold ? shown(card.quote) : card.isEnded ? card.last : (card.title ?? card.work)

  return (
    <Box key={card.id} borderStyle="round" borderColor={card.isIdle ? 'subtle' : line} paddingX={1} flexDirection="column" alignItems="center" width={width}>
      {Icon(kit, card.id, card.isRunning)}
      {Middle(kit, inner, cells(name), Name(kit, card.id, onWatch, name))}
      <Text color={card.tint} bold={!card.isIdle} dimColor={card.isIdle} wrap="truncate-end">
        {fit(statusOf(kit, card), inner)}
      </Text>
      <Text color={isTold ? line : undefined} italic={isTold && !isGesture(card.quote)} wrap="truncate-end">
        {fit(about, inner)}
      </Text>
    </Box>
  )
}

/** Cuts to a row: the three the comic is about fill one. */
const ACROSS = CORE.length

/** Characters as rows of cuts, three across; a row with fewer has them in its middle. */
const Panels = (kit: Kit, scene: Scene, ids: readonly MemberId[], width: number, onWatch: OnWatch): RenderElement[] => {
  const each = Math.floor(width / ACROSS)
  const rows: MemberId[][] = []

  for (let at = 0; at < ids.length; at += ACROSS) rows.push(ids.slice(at, at + ACROSS))

  return rows.map((row, index) => (
    <kit.Box key={`cuts-${row[0] ?? index}`} justifyContent="center" width={width}>
      {row.map(id => Panel(kit, scene.lang, cardOf(id, scene), each, onWatch))}
    </kit.Box>
  ))
}

/** What the rule over the conversation is written with: its label, the ways back and on, and the way to the conversation alone. */
type TalkWords = readonly [label: string, older: string, newer: string, story: string]

/**
 * The rule over the conversation. Where more was said than the page holds,
 * it has the way back through it at its end: the lines before these, the
 * lines after, and which of them are shown while it is turned back. Last is
 * the way to the conversation alone, and from there back to the whole page.
 * Short of room it is written with fewer words, so that it stays one row.
 */
const TalkRule = (kit: Kit, scene: Scene, count: number, width: number, { onTalk, onStory }: Pick<PaneActs, 'onTalk' | 'onStory'>): RenderElement => {
  const { Box, Text, Button } = kit
  const { from, to } = shownOf(scene, count)
  const total = scene.feed.length
  const back = total - to
  const size = Math.max(1, count)
  const range = `${from + 1}~${to}/${total}`
  // The page of the conversation alone, and the way back from it to the whole page.
  const words = wordsOf(scene)
  const tries: readonly TalkWords[] = [
    [back > 0 ? words.earlier(range) : words.talk, words.older, words.newer, scene.isTalkOnly ? words.all : words.only],
    [back > 0 ? range : words.talk, '▲', '▼', scene.isTalkOnly ? words.all : words.only],
    [back > 0 ? range : words.talk, '▲', '▼', scene.isTalkOnly ? words.allShort : words.talk],
  ]
  const usedBy = ([, older, newer, story]: TalkWords): number => (from > 0 ? cells(older) + 2 : 0) + (back > 0 ? cells(newer) + 2 : 0) + cells(story) + 2
  const [label, older, newer, story] = tries.find(one => cells(one[0]) + 2 + usedBy(one) <= width) ?? tries[tries.length - 1] ?? ['', '', '', '']

  return (
    <Box width={width}>
      {Rule(kit, label, width - usedBy([label, older, newer, story]))}
      {from > 0 && <Text>{'  '}</Text>}
      {from > 0 && <Button key="talk-older" label={older} plain onPress={() => onTalk(Math.min(total - 1, back + size))} />}
      {back > 0 && <Text>{'  '}</Text>}
      {back > 0 && <Button key="talk-newer" label={newer} plain onPress={() => onTalk(Math.max(0, back - size))} />}
      <Text>{'  '}</Text>
      <Button key="talk-only" label={story} plain dimColor={!scene.isTalkOnly} onPress={() => onStory()} />
    </Box>
  )
}

/** A dim rule across the page with a label in its middle, the label cut to what the rule holds. */
const Rule = (kit: Kit, label: string, width: number): RenderElement => {
  const text = fit(label, width - 2)
  const side = Math.max(0, width - cells(text) - 2)
  const middle = text === '' ? '─'.repeat(Math.min(2, Math.max(0, width))) : ` ${text} `

  return <kit.Text dimColor>{`${'─'.repeat(Math.floor(side / 2))}${middle}${'─'.repeat(side - Math.floor(side / 2))}`}</kit.Text>
}

// ---- the sheet: what one character is doing, for the one who pressed its name

type SheetRow = { label: string; text: string; tint?: Color; isPath?: boolean }
type Sheet = { id: MemberId; rows: SheetRow[]; canPick: boolean }

/** Tasks in hand a sheet tells one by one before it counts the rest. */
const LISTED = 3
const LABEL = 8

/** One task in hand: its name, the engine and how long it has run, the tool in its hand, why it waits, where its result goes. */
const taskRows = (lang: Lang, task: Task, now: number, label: string): SheetRow[] => {
  const words = WORDS[lang]
  const tint = TINT[task.status]
  const rows: SheetRow[] = [
    { label, text: `${MARK[task.status]} ${titleOf(lang, task)}`, ...(tint === undefined ? {} : { tint }) },
    { label: '', text: `  ${engineOf(words, task)} · ${words.status[task.status]} ${clock(elapsed(task, now))}` },
  ]
  const doing = doingOf(words, task)

  if (doing !== '') rows.push({ label: '', text: `  ${doing}` })
  if (task.status === 'waiting' && task.note[lang] !== '') rows.push({ label: '', text: `  ${task.note[lang]}` })
  if (task.out !== undefined) rows.push({ label: words.labels.result, text: task.out, isPath: true })

  return rows
}

const saidRows = (scene: Scene, id: MemberId): SheetRow[] =>
  scene.feed
    .filter(one => one.member === id)
    .slice(-2)
    .map((one, index) => ({ label: index === 0 ? wordsOf(scene).labels.said : '', text: `${shown(one.quote[scene.lang])}${one.note[scene.lang] === '' ? '' : ` ${one.note[scene.lang]}`}` }))

/** The sheet of the character the person asked about; none where they asked about no one. */
const sheetOf = (scene: Scene): Sheet | undefined => {
  const id = scene.watched
  const { lang } = scene

  if (id === null) return undefined
  const words = wordsOf(scene)
  const { labels } = words
  const cost = spentBy(scene)[id]
  const paid: SheetRow[] = isSpent(cost) ? [{ label: labels.pay, text: spent(scene.lang, cost) }] : []

  if (id === 'rodo') return { id, rows: [{ label: labels.now, text: words.bell }, ...saidRows(scene, id)], canPick: false }
  if (id === LEAD) {
    const active = scene.tasks.filter(isActive).sort((a, b) => a.startedAt - b.startedAt)
    const day = tally(scene)
    const own = aidOf(scene, LEAD)
    const rows: SheetRow[] = [{ label: labels.now, text: active.length > 0 ? words.conducting(active.length) : own === undefined ? words.awaiting : `${MARK.running} ${words.alone} · ${own.what[lang]}` }]

    for (const task of active.slice(0, LISTED * 2)) {
      const tint = TINT[task.status]

      rows.push({ label: '', text: `${MARK[task.status]} ${nameOf(scene, task.member)}: ${titleOf(lang, task)} · ${words.status[task.status]} ${clock(elapsed(task, scene.now))}`, ...(tint === undefined ? {} : { tint }) })
    }
    if (active.length > LISTED * 2) rows.push({ label: '', text: words.more(active.length - LISTED * 2) })
    if (day !== undefined) rows.push({ label: labels.today, text: words.today(day.done, day.failed) })

    return { id, rows: [...rows, ...paid, ...saidRows(scene, id)], canPick: true }
  }

  const own = tasksOf(scene, id)
  const active = own.filter(isActive)
  const ended = own.find(task => !isActive(task))
  const aid = aidOf(scene, id)
  const resting: SheetRow = aid === undefined ? { label: labels.now, text: `${words.rest} · ${jobOf(lang, id, scene.roles)}` } : { label: labels.now, text: `${MARK.running} ${words.aidingLead} · ${aid.what[lang]}` }
  const rows: SheetRow[] = active.length === 0 ? [resting] : active.slice(0, LISTED).flatMap((task, index) => taskRows(lang, task, scene.now, index === 0 ? labels.now : ''))

  if (active.length > LISTED) rows.push({ label: '', text: words.more(active.length - LISTED) })
  if (ended !== undefined) {
    const tint = TINT[ended.status]
    // The report is the first of the lines handed back: it stands as this language has it, over the rest as they were written.
    const told = ended.report === undefined ? [] : [ended.report[lang], ...(ended.summary ?? []).slice(1)]

    rows.push({ label: labels.ended, text: `${MARK[ended.status]} ${titleOf(lang, ended)} · ${words.spoken(elapsed(ended, scene.now))}`, ...(tint === undefined ? {} : { tint }) })
    rows.push(...told.map((line, index) => ({ label: index === 0 ? labels.report : '', text: line })))
  }

  return { id, rows: [...rows, ...paid, ...saidRows(scene, id)], canPick: true }
}

/** Only one who takes tasks has a role the person can change. */
const hasRole = (id: MemberId): boolean => WORKERS.includes(id)

/** A role to give, as its button is labeled. */
type RoleButton = { role: WorkRole; label: string }

/** Rows of the roles a sheet may be given where it is as narrow as a pane gets: a role to a row. */
const ROLE_ROWS = WORK_ROLES.length
/** The cells the roles to give take in a row, as a language names them: each with its mark, and a cell between two. */
const roleCells = (lang: Lang): number => WORK_ROLES.reduce((sum, one) => sum + cells(CAST[lang].roles[one]) + 2, -1)

/**
 * The roles to give, as rows of buttons in a width, `most` rows at the most.
 * Each is named whole where the rows are there for it, as many to a row as go
 * in. With fewer rows, the names are cut to share those; a width the cut
 * names cannot be told apart in has no buttons, for a button that may give
 * either of two roles is worse than none.
 */
const roleRowsOf = (lang: Lang, width: number, most: number): RoleButton[][] => {
  const whole = WORK_ROLES.map(role => ({ role, label: CAST[lang].roles[role] }))
  const flowed: RoleButton[][] = []
  let used = 0

  if (most <= 0) return []
  for (const one of whole) {
    const wanted = cells(one.label) + 1
    const last = flowed[flowed.length - 1]

    if (last !== undefined && used + 1 + wanted <= width) {
      last.push(one)
      used += 1 + wanted
    } else {
      flowed.push([one])
      used = wanted
    }
  }
  if (flowed.length <= most && whole.every(one => cells(one.label) + 1 <= width)) return flowed
  const each = Math.ceil(whole.length / most)
  const room = Math.floor((width - (each - 1)) / each) - 1
  const cut = whole.map(one => ({ ...one, label: clip(one.label, room) }))

  if (cut.some(one => one.label === '') || new Set(cut.map(one => one.label)).size < cut.length) return []

  return Array.from({ length: Math.ceil(cut.length / each) }, (_, row) => cut.slice(row * each, (row + 1) * each))
}

/** Rows a sheet's buttons take under its head, in a width: the one that hands the character the next prompt, and the roles. */
const controlRows = (sheet: Sheet, lang: Lang, width: number): number =>
  Number(sheet.canPick) + (hasRole(sheet.id) ? roleRowsOf(lang, width - 4, ROLE_ROWS).length : 0)

/** Rows a sheet takes in a width, frame and all. */
const sheetRows = (sheet: Sheet | undefined, lang: Lang, width: number): number => (sheet === undefined ? 0 : sheet.rows.length + 3 + controlRows(sheet, lang, width))

/**
 * The sheet, framed in the character's color: who and in what state, the
 * rows, the roles to give the character with the one it has marked, a button
 * that hands the character the person's next prompt, and one that puts the
 * sheet away. Given fewer rows than it would take, it draws no more than
 * those, and keeps what can be pressed the longest: the rows go first, from
 * the last up, then the roles, cut short before they are left out, then the
 * button, down to the head alone in its frame, with the way to put it away.
 */
const SheetCard = (kit: Kit, scene: Scene, sheet: Sheet, width: number, acts: PaneActs, rows = sheetRows(sheet, scene.lang, width)): RenderElement => {
  const { Box, Text, Button } = kit
  const inner = width - 4
  const words = wordsOf(scene)
  const labels = CAST[scene.lang].roles
  const card = cardOf(sheet.id, scene)
  // The head keeps the way to put the sheet away: the name is cut to what that leaves, and the state and what follows it are there with room.
  const name = nameIn(scene.lang, sheet.id, Math.max(1, inner - cells(words.close) - 3))
  const stateRoom = inner - (cells(name) + 2) - 1 - cells(words.close) - 1
  const hasState = cells(statusOf(kit, card)) <= stateRoom
  const subRoom = stateRoom - cells(statusOf(kit, card)) - 1
  const isPicked = scene.picked === sheet.id
  const ask = sheet.id === LEAD ? words.askLead : words.askFriend
  const role = roleOf(sheet.id, scene.roles)
  const own = words.ownRole(labels[MEMBERS[sheet.id].role])
  const across = roleCells(scene.lang)
  const spare = rows - 3
  const canPick = sheet.canPick && spare >= 1
  const roleRows = hasRole(sheet.id) ? roleRowsOf(scene.lang, inner, spare - Number(canPick)) : []
  // With room beside the roles in their one row, what the row is and the role the character has of its own are told.
  const hasRoleLabel = roleRows.length === 1 && inner >= LABEL + across
  const roleRoom = inner - LABEL - across - 1

  return (
    <Box key="sheet" borderStyle="round" borderColor={lineOf(kit, sheet.id)} paddingX={1} flexDirection="column" width={width}>
      <Box justifyContent="space-between" width={inner}>
        <Box gap={1}>
          {Badge(kit, sheet.id, name)}
          {hasState && State(kit, card)}
          {subRoom >= 4 && <Text dimColor>{fit(card.sub, subRoom)}</Text>}
        </Box>
        <Button key="watch-close" label={words.close} plain dimColor onPress={() => acts.onWatch(null)} />
      </Box>
      {sheet.rows.slice(0, Math.max(0, spare - Number(canPick) - roleRows.length)).map((row, index) => (
        <Text key={`sheet-${index}`} wrap="truncate-end">
          <Text dimColor>{pad(row.label, LABEL)}</Text>
          <Text color={row.tint}>{row.isPath === true ? fitEnd(row.text, inner - LABEL) : fit(row.text, inner - LABEL)}</Text>
        </Text>
      ))}
      {roleRows.map((row, index) => (
        <Box key={`roles-${index}`} gap={1}>
          {hasRoleLabel && <Text dimColor>{pad(words.labels.role, LABEL - 1)}</Text>}
          {row.map(one => (
            <Button key={`role-${sheet.id}-${one.role}`} label={`${one.role === role ? '▶' : '▷'}${one.label}`} plain dimColor={one.role !== role} onPress={() => acts.onRole(sheet.id, one.role)} />
          ))}
          {hasRoleLabel && role !== MEMBERS[sheet.id].role && roleRoom >= cells(own) + 1 && <Text dimColor>{own}</Text>}
        </Box>
      ))}
      {canPick && (
        <Box>
          <Button key={`pick-${sheet.id}`} label={fit(isPicked ? words.picked : ask, inner)} plain dimColor={!isPicked} onPress={() => acts.onPick(sheet.id)} />
        </Box>
      )}
    </Box>
  )
}

/** Ones with no card, named together in a row under what they are doing. */
type Group = { label: string; ids: readonly MemberId[]; isAtWork: boolean }
/** A group as a row has room for it: its label with what parts it from the group before, the ones named, and how many are not. */
type Named = { head: string; shown: MemberId[]; more: number; isAtWork: boolean }

/** The cells a count of the ones not named is kept room for. */
const MORE_CELLS = 4

/** The groups of the ones with no card that have anyone in them: the ones at work first. */
const groupsOf = (scene: Pick<Scene, 'lang'>, hidden: readonly MemberId[], bench: readonly MemberId[]): Group[] =>
  [
    { label: wordsOf(scene).atWorkLabel, ids: hidden, isAtWork: true },
    { label: wordsOf(scene).rest, ids: bench, isAtWork: false },
  ].filter(group => group.ids.length > 0)

/** One group in the cells it is given: its label, the names that go in with room kept for a count, and the count of the rest. With no room for the label, the count alone. */
const groupIn = (lang: Lang, { label, ids, isAtWork }: Group, lead: string, width: number): Named => {
  const head = `${lead}${label} `
  const shown: MemberId[] = []
  let used = cells(head)

  if (used > width - MORE_CELLS + 1) return { head: '', shown, more: ids.length, isAtWork }
  for (const [index, id] of ids.entries()) {
    const wanted = cells(shortName(lang, id)) + (index === 0 ? 0 : 3)

    if (used + wanted > width - MORE_CELLS) break
    shown.push(id)
    used += wanted
  }

  return { head, shown, more: ids.length - shown.length, isAtWork }
}

/** The count of the ones a group does not name, parted from the last name before it. */
const moreOf = ({ head, shown, more }: Named): string => (more === 0 ? '' : `${head !== '' && shown.length === 0 ? '' : ' '}+${more}`)

/** The cells a group as a row has room for it takes. */
const namedCells = (lang: Lang, named: Named): number =>
  cells(named.head) + named.shown.reduce((sum, id, index) => sum + cells(shortName(lang, id)) + (index === 0 ? 0 : 3), 0) + cells(moreOf(named))

/**
 * The ones with no card as one row of names, the ones at work told apart from
 * the ones resting. Both labels and a count for each are given their room
 * before any name is, so that the ones at work never push the ones resting
 * off the row unsaid. A row with no room for both labels has the first alone,
 * and counts the rest with its own.
 */
const namedIn = (scene: Pick<Scene, 'lang'>, groups: readonly Group[], width: number): Named[] => {
  const [first, second] = groups
  const least = (group: Group): number => cells(group.label) + MORE_CELLS

  if (first === undefined) return []
  if (second === undefined) return [groupIn(scene.lang, first, '', width)]
  if (least(first) + 2 + least(second) > width) {
    const alone = groupIn(scene.lang, first, '', width)

    return [{ ...alone, more: alone.more + second.ids.length }]
  }
  const named = groupIn(scene.lang, first, '', width - 2 - least(second))

  return [named, groupIn(scene.lang, second, '  ', width - namedCells(scene.lang, named))]
}

export type Density = 'full' | 'slim'

const SLIM_ROWS = 2
const SEAT_ROWS = ICON_ROWS + 1
/** The fewest rows a page of cuts is drawn in: the title, the three, and one cut of the conversation. */
const FULL_ROWS = 1 + PANEL_ROWS + 2 + 1 + ART_ROWS + 3

/** How long a guest keeps its cut after its work ended, before it goes back to the bench. */
const CARD_LINGER_MS = 30_000

/** The characters on the page: the three the comic is about, then each guest with work in hand or only just ended. */
export const carded = (scene: Scene): MemberId[] => {
  const held = new Set(scene.tasks.filter(task => isRunning(task) || (task.endedAt !== undefined && scene.now - task.endedAt < CARD_LINGER_MS)).map(task => task.member))

  return [...CORE, ...GUESTS.filter(id => held.has(id))]
}

export type Plan = {
  density: Density
  /** On the page, in the order they are drawn: the three, then the guests with work. */
  cards: MemberId[]
  /** At work, with no card for want of room. */
  hidden: MemberId[]
  /** With no work in hand: waiting as characters. */
  bench: MemberId[]
  /** Seats to a row where the bench is drawn as icons; 0 where it is a line of names. */
  strip: number
  /** Cuts of the conversation on a page of cuts, lines of it in a list; 0 where there is no room. */
  talk: number
  /** Of the rows under the cards (the bench, the usage, the help, kept in that order), how many there is room for. */
  extras: number
  /** Whether the person asked about a character: its sheet is drawn. */
  hasSheet: boolean
  /** Whether the sheet is all there is room for besides the title. */
  isSheetOnly: boolean
  /** Whether the ones at work with no card and the ones resting have a row of names each: one row does not name them all, and there is a row to spare. */
  isBenchSplit: boolean
}

/**
 * The layout the room holds. A page of cuts where it is wide and tall enough
 * for the three and one cut of the conversation. The conversation has its
 * last three lines; the rows left go to the bench's icons, then to more of
 * the conversation, and a page too long for its pane scrolls. A list, two
 * rows a character, where it is not.
 */
export const planOf = (scene: Scene, room: Room): Plan => {
  const all = carded(scene)
  const busy = new Set(busyOf(scene))
  const sheet = sheetOf(scene)
  const asked = sheetRows(sheet, scene.lang, room.columns)

  // The conversation alone: every row under the title and the rule is its own, a cut each where the pane is wide and has the rows for one, a line each where it is not.
  if (scene.isTalkOnly) {
    const isWide = room.columns >= 50 && room.rows - 2 >= ART_ROWS
    const talk = Math.max(1, isWide ? Math.floor((room.rows - 2) / ART_ROWS) : room.rows - 2)

    return { density: isWide ? 'full' : 'slim', cards: [], hidden: [], bench: ORDER.filter(id => !CORE.includes(id)), strip: 0, talk, extras: 0, hasSheet: false, isSheetOnly: false, isBenchSplit: false }
  }

  if (room.columns >= 50 && room.rows >= FULL_ROWS) {
    const guests = all.length - CORE.length
    const bench = ORDER.filter(id => !all.includes(id))
    const guestRows = guests === 0 ? 0 : 1 + Math.ceil(guests / ACROSS) * (PANEL_ROWS + 2)
    const usage = scene.isUsageOpen ? usageRows(scene) : 1
    const base = Math.max(1, Math.min(MIN_CUTS, scene.feed.length))
    let left = room.rows - (1 + PANEL_ROWS + 2 + asked + guestRows + 1 + base * ART_ROWS + 1 + usage + 1)
    const widest = Math.max(1, Math.floor((room.columns + 1) / (ICON_COLUMNS + 1)))
    const seatRows = Math.ceil(bench.length / widest)
    // The seats are shared out evenly: seven sit four and three, not six and one.
    const strip = bench.length > 0 && left >= seatRows * SEAT_ROWS ? Math.ceil(bench.length / seatRows) : 0

    if (strip > 0) left -= seatRows * SEAT_ROWS
    const talk = base + Math.max(0, Math.min(MAX_CUTS - base, Math.floor(left / ART_ROWS), scene.feed.length - base))

    return { density: 'full', cards: all, hidden: [], bench, strip, talk, extras: 3, hasSheet: sheet !== undefined, isSheetOnly: false, isBenchSplit: false }
  }

  const around = 1 + asked + 3
  const held = Math.max(1, Math.min(all.length, Math.floor((room.rows - around) / SLIM_ROWS)))
  // Where not everyone fits: 하치와레, then the ones at work, then the other two of the three, then the ones who have finished.
  const rank = (id: MemberId): number => (id === LEAD ? 0 : busy.has(id) ? 1 : CORE.includes(id) ? 2 : 3)
  const chosen = new Set([...all].sort((a, b) => rank(a) - rank(b)).slice(0, held))
  const cards = all.filter(id => chosen.has(id))
  const hidden = all.filter(id => !chosen.has(id) && busy.has(id))
  const bench = ORDER.filter(id => !chosen.has(id) && !hidden.includes(id))
  const left = room.rows - around - cards.length * SLIM_ROWS
  const talk = left >= 3 ? Math.min(3, left) : 0
  const extras = Math.max(0, Math.min(3, room.rows - 1 - asked - cards.length * SLIM_ROWS))
  // With no room for a card beside it, the sheet is what the person asked for.
  const isSheetOnly = sheet !== undefined && room.rows - around < SLIM_ROWS
  const isBenchSplit = left >= 1 && talk === 0 && hidden.length > 0 && bench.length > 0 && namedIn(scene, groupsOf(scene, hidden, bench), room.columns).some(group => group.more > 0)

  return { density: 'slim', cards, hidden, bench, strip: 0, talk, extras, hasSheet: sheet !== undefined, isSheetOnly, isBenchSplit }
}

/** The ones with no card in a row of names, in its groups: the ones at work, and the ones resting. */
const NameRow = (kit: Kit, scene: Scene, groups: readonly Group[], width: number, onWatch: OnWatch, key: string): RenderElement => {
  const { Box, Text } = kit

  return (
    <Box key={key} width={width}>
      {namedIn(scene, groups, width).flatMap(named => [
        named.head !== '' && (
          <Text key={`label-${named.head}`} bold={named.isAtWork} dimColor={!named.isAtWork}>
            {named.head}
          </Text>
        ),
        ...named.shown.flatMap((id, index) => [
          index > 0 && (
            <Text key={`dot-${id}`} dimColor>
              {' · '}
            </Text>
          ),
          <Box key={id}>{Name(kit, id, onWatch, shortName(scene.lang, id), !named.isAtWork)}</Box>,
        ]),
        named.more > 0 && (
          <Text key={`more-${named.head}`} dimColor>
            {moreOf(named)}
          </Text>
        ),
      ])}
    </Box>
  )
}

/**
 * The ones with no card, waiting as characters. Where there is room, rows of
 * seats under a rule, shared out evenly and centered, each an icon over its
 * name to press, one whose work in this wave has ended marked so; where not,
 * a line of names, or one for the ones at work and one for the ones resting.
 */
const Bench = (kit: Kit, scene: Scene, plan: Plan, width: number, onWatch: OnWatch): RenderElement => {
  const { Box } = kit
  const groups = groupsOf(scene, plan.hidden, plan.bench)

  if (plan.strip === 0 && plan.isBenchSplit) {
    return (
      <Box flexDirection="column" width={width}>
        {groups.map((group, index) => NameRow(kit, scene, [group], width, onWatch, `names-${index}`))}
      </Box>
    )
  }
  if (plan.strip === 0) return NameRow(kit, scene, groups, width, onWatch, 'names')
  const each = Math.floor(width / plan.strip)
  const rows: MemberId[][] = []
  const stage = onStage(scene)
  const named = (id: MemberId): string => {
    const ended = stage.find(task => task.member === id)
    const name = nameIn(scene.lang, id, each - 4, each - (ended === undefined ? 1 : 3))

    return ended === undefined ? name : `${name} ${MARK[ended.status]}`
  }

  for (let at = 0; at < plan.bench.length; at += plan.strip) rows.push(plan.bench.slice(at, at + plan.strip))

  return (
    <Box flexDirection="column" width={width}>
      {Rule(kit, wordsOf(scene).bench, width)}
      {rows.map((row, index) => (
        <Box key={`bench-${index}`} justifyContent="center" width={width}>
          {row.map(id => (
            <Box key={id} flexDirection="column" alignItems="center" width={each}>
              {Icon(kit, id)}
              {Middle(kit, each, cells(named(id)), Name(kit, id, onWatch, named(id), true))}
            </Box>
          ))}
        </Box>
      ))}
    </Box>
  )
}

/** The usage in one line to press: the card is drawn in its place. */
const UsageLine = (kit: Kit, scene: Scene, width: number, onUsage: () => void): RenderElement => {
  const meters = metersOf(scene)
  const label = meters.length === 0 ? wordsOf(scene).seeUsage : meters.map(meter => `${meter.label} ${Math.round(meter.percent)}%`).join(' · ')

  return (
    <kit.Box width={width}>
      <kit.Button key="usage-more" label={fit(label, width)} plain dimColor onPress={() => onUsage()} />
    </kit.Box>
  )
}

/**
 * The pane, laid out as a page of the comic: the three it is about in a row
 * of cuts, the sheet of the character the person asked about, the guests at
 * work in cuts of the same shape, the last of the conversation as balloons,
 * the ones resting as characters, and the usage in a line.
 */
export const drawPane = (kit: Kit, scene: Scene, isOn: boolean, room: Room, acts: PaneActs): RenderElement => {
  const { Box, Text } = kit
  const width = Math.max(16, Math.min(room.columns, 84))
  const plan = planOf(scene, { columns: width, rows: room.rows })
  const busy = busyOf(scene)
  const isTrioAtWork = CORE.some(id => aidOf(scene, id) !== undefined)
  const waiting = waitingOf(scene).length
  const words = wordsOf(scene)
  const head = busy.length > 0 ? words.busy(busy.length) : isTrioAtWork ? words.trio : waiting > 0 ? words.waiting(waiting) : words.rest
  const sheet = plan.hasSheet ? sheetOf(scene) : undefined
  const isFull = plan.density === 'full'
  const guests = plan.cards.filter(id => !CORE.includes(id))
  const title = (
    <Box justifyContent="space-between" width={width}>
      <Text wrap="truncate-end">
        <Text backgroundColor={PINK} color="#000000" bold>
          {` ${words.brand} `}
        </Text>
        <Text bold>{` ${head}`}</Text>
      </Text>
      <Text color={isOn ? toneOf(PINK, kit.isLight) : undefined} dimColor={!isOn}>
        {isOn ? words.on : words.off}
      </Text>
    </Box>
  )

  if (scene.isTalkOnly) {
    const { from, to } = shownOf(scene, plan.talk)

    return (
      <Box flexDirection="column" width={width}>
        {title}
        {TalkRule(kit, scene, plan.talk, width, acts)}
        {isFull ? Page(kit, scene, width, plan.talk) : (scene.feed.length === 0 ? [waitingSaid] : scene.feed.slice(from, to)).map((one, index) => TalkRow(kit, scene.lang, one, width, `said-${one.at}-${index}`))}
      </Box>
    )
  }

  // With room for little else, the answer to what the person asked comes first, and before the title where the rows are short: the title is there once the sheet has its buttons and a row to tell under it.
  if (plan.isSheetOnly && sheet !== undefined) {
    const hasTitle = room.rows - 1 >= 3 + controlRows(sheet, scene.lang, width) + Math.min(1, sheet.rows.length)

    return (
      <Box flexDirection="column" width={width}>
        {hasTitle && title}
        {SheetCard(kit, scene, sheet, width, acts, room.rows - Number(hasTitle))}
      </Box>
    )
  }

  return (
    <Box flexDirection="column" width={width}>
      {title}
      {isFull && Panels(kit, scene, CORE, width, acts.onWatch)}
      {sheet !== undefined && SheetCard(kit, scene, sheet, width, acts)}
      {isFull && guests.length > 0 && Rule(kit, words.workers, width)}
      {isFull && Panels(kit, scene, guests, width, acts.onWatch)}
      {isFull && TalkRule(kit, scene, plan.talk, width, acts)}
      {plan.talk > 0 && (isFull ? Page(kit, scene, width, plan.talk) : Talk(kit, scene, width, plan.talk, false))}
      {!isFull && plan.cards.map(id => SlimCard(kit, scene.lang, cardOf(id, scene), width, acts.onWatch))}
      {plan.extras >= 1 && Bench(kit, scene, plan, width, acts.onWatch)}
      {plan.extras >= 2 && (scene.isUsageOpen && isFull ? UsageCard(kit, scene, width, acts.onUsage) : UsageLine(kit, scene, width, acts.onUsage))}
      {plan.extras >= 3 && (
        <Text dimColor wrap="truncate-end">
          {fit(words.help, width)}
        </Text>
      )}
    </Box>
  )
}

// ---- plain text, for a command's answer and a surface with no colors

export const rosterLines = (scene: Scene): string[] =>
  [LEAD, ...WORKERS].map(id => {
    const card = cardOf(id, scene)

    return `${MEMBERS[id].mark} ${card.name} (${CAST[scene.lang].roles[roleOf(id, scene.roles)]}) ${card.status}${card.isIdle ? '' : ` · ${card.work}`}`
  })

/** The conversation as plain lines, oldest first. */
export const talkLines = (scene: Scene, lines: number): string[] =>
  scene.feed.slice(-lines).map(said => `${nameOf(scene, said.member)}: ${shown(said.quote[scene.lang])}${said.note[scene.lang] === '' ? '' : ` (${said.note[scene.lang]})`}`)

/** The usage as plain lines: what `/chiikawa usage` prints. */
export const usageLines = (scene: Scene): string[] => {
  const words = wordsOf(scene)
  const by = spentBy(scene)
  const lines = metersOf(scene).map(meter => `${pad(meter.label, labelCells(words))}${bar(meter.percent)} ${meter.text}`)

  if (scene.usage?.usd !== undefined) lines.push(words.sessionCost(scene.usage.usd.toFixed(2)))
  const spenders = spendersOf(scene)

  if (spenders.length > 0) lines.push(words.pay)
  for (const id of spenders) lines.push(`${MEMBERS[id].mark} ${nameOf(scene, id)}: ${spent(scene.lang, by[id])}`)

  return lines.length === 0 ? [words.noUsage] : lines
}

